/* US-ACTION-ICONS:START */
.us-panel-action.us-icon-button > svg:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  flex: none;
  width: 18px;
  height: 18px;
  pointer-events: none;
}

/* Existing TextButton/btn controls with explicitly authored Tabler children.
   us-icon-button is an optional compact presentation modifier, not a command.
   Do not infer actions from labels/IDs or replace native input/image controls. */
:is(a, button):is(.TextButton, .btn):has(> .ti):not(:where(.Facebook, .LinkedIn, .FeatureButton)):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  vertical-align: middle;
}

:is(.us-panel-action, .us-banner__menu-item):has(> .ti):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
}

:is(a, button):is(.TextButton, .btn) > .ti:not(:where(.us-report-no-styling, .us-report-no-styling *)),
:is(.us-panel-action, .us-banner__menu-item) > .ti:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  flex: 0 0 18px;
  width: 18px;
  font-size: 18px;
  line-height: 1;
  text-align: center;
  color: inherit;
  pointer-events: none;
}

:where(a, button):is(.TextButton, .btn).us-icon-button:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  --button-bg: transparent;
  --button-hover-bg: var(--icon-hover-bg);
  --button-text: var(--text-link);
  --button-hover-text: var(--icon-hover-colour);
  --button-decoration: none;
}

/* Keyboard focus shows the hover tint as well as the focus ring. */
:where(a, button):is(.TextButton, .btn).us-icon-button:focus-visible:not(:where(:disabled, [disabled], .disabled, .aspNetDisabled, [aria-disabled="true"])):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  --button-current-bg: var(--button-hover-bg);
  --button-current-text: var(--button-hover-text);
}

:where(a, button):is(.TextButton, .btn).us-icon-button.DangerButton:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  --button-hover-bg: var(--danger-bg);
  --button-text: var(--danger);
  --button-hover-text: var(--danger);
}

:where(a, button):is(.TextButton, .btn).us-icon-button.SuccessButton:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  --button-hover-bg: var(--success-bg);
  --button-text: var(--success);
  --button-hover-text: var(--success);
}

/* Match native grid/button specificity for sizing, without changing controls
   that have not explicitly opted into the compact modifier. */
:is(a, button):is(.TextButton, .btn).us-icon-button:not(:where(.us-report-no-styling, .us-report-no-styling *)),
.RadGrid.RadGrid :is(a, button):is(.TextButton, .btn).us-icon-button:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  flex: 0 0 auto;
  width: 36px;
  min-width: 36px;
  height: 36px;
  min-height: 36px;
  padding: 0;
  margin: 0;
  gap: 0;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  line-height: 1;
  text-decoration: none;
}

/* Touch sizes go by width, not pointer type (owner, 5 October 2026).
   Browsers on touchscreen laptops can report the touchscreen as the only
   pointer (Edge on Windows reports no mouse or trackpad at all), so a
   pointer: coarse or hover: none test gave docked laptops 44px buttons on a
   mouse-driven screen. Every former touch query in the theme is now
   (max-width: 950px). */
@media (max-width: 950px) {
  :root {
    --panel-header-min-height: 56px;
    --panel-header-action-height: 44px;
  }

  :is(a, button):is(.TextButton, .btn).us-icon-button:not(:where(.us-report-no-styling, .us-report-no-styling *)),
  .RadGrid.RadGrid :is(a, button):is(.TextButton, .btn).us-icon-button:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
    width: 44px;
    min-width: 44px;
    height: 44px;
    min-height: 44px;
  }
}

/* Shared JS keeps this visual label available on hover without intercepting
   nearby controls. Text comes from aria-label; focus and Escape also work. */
.us-action-tooltip:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  position: fixed;
  pointer-events: none;
  z-index: var(--z-tooltip);
  max-width: min(280px, calc(100vw - 16px));
  padding: 6px 10px;
  border-radius: var(--radius-sm);
  background: var(--brand-950);
  color: var(--text-inverse);
  box-shadow: var(--shadow);
  font: 400 12px/1.5 var(--font-ui);
  overflow-wrap: anywhere;
}

/* The taskbar's mobile results use layer 100000; keep their labels above it. */
.us-action-tooltip[data-us-taskbar-tooltip]:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  z-index: max(var(--z-tooltip),100001);
}

.us-action-tooltip[hidden]:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: none;
}

/* Registry conflicts stay keyboard-focusable so their explanation is available. */
:root .us-action-conflict:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  position: relative;
  opacity: 1;
  pointer-events: auto;
  cursor: help;
}

:root .us-action-conflict > svg.us-action-conflict-icon {
  flex: none;
  width: 16px;
  height: 16px;
  margin-inline-start: 6px;
  color: var(--danger);
  vertical-align: middle;
}

:root .us-action-conflict.us-icon-button > svg.us-action-conflict-icon {
  position: absolute;
  right: -3px;
  top: -3px;
  width: 15px;
  height: 15px;
  margin: 0;
  background: var(--bg-surface);
  border-radius: 3px;
}

.us-action-conflict-notice {
  position: fixed;
  bottom: 20px;
  left: 20px;
  z-index: var(--z-tooltip);
  box-sizing: border-box;
  max-width: calc(100vw - 40px);
  padding: 12px 16px;
  border: 1px solid var(--danger);
  border-radius: var(--radius);
  background: var(--danger-bg);
  color: var(--text-strong);
  font: 13px/1.5 var(--font-ui);
}

.us-action-conflict-notice[hidden] {
  display: none;
}

/* Unified commands use normal theme controls in every placement. */
.us-command:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.us-command > svg:not(.us-action-conflict-icon) {
  width: 18px;
  height: 18px;
  flex: none;
}

.us-command.us-actions__item {
  justify-content: flex-start;
}

.us-command[data-us-command-hidden] {
  display: none !important;
}

.us-command[aria-disabled="true"]:not(.us-action-conflict) {
  cursor: help;
}

.us-command[aria-busy="true"] {
  cursor: progress;
}

/* An icon action that is running (data-us-command-state="busy", such as a
   download or a preview loading) swaps its icon for the theme's button
   spinner, in the link colour rather than the greyed disabled colour, so it
   reads as working rather than unavailable (owner, 5 October 2026). The
   spinner fades in; reduced motion shows it still. */
.us-command.us-icon-button[data-us-command-state="busy"] > :is(.ti, svg:not(.us-action-conflict-icon)) {
  display: none;
}

.us-command.us-icon-button[data-us-command-state="busy"]::before {
  content: "";
  box-sizing: border-box;
  flex: none;
  width: 16px;
  height: 16px;
  border: 2px solid var(--text-link);
  border-right-color: transparent;
  border-radius: 50%;
  animation:
    us-button-spin .8s linear infinite,
    us-command-busy-in 150ms cubic-bezier(.2, 0, 0, 1);
}

@keyframes us-command-busy-in {
  from {
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .us-command.us-icon-button[data-us-command-state="busy"]::before {
    animation: none;
  }
}

.us-command-notice {
  position: fixed;
  bottom: 20px;
  left: 20px;
  z-index: var(--z-tooltip);
  max-width: min(620px,calc(100vw - 40px));
  padding: 12px 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--bg-surface);
  color: var(--text-strong);
  box-shadow: var(--shadow-lg);
  font: 13px/1.5 var(--font-ui);
  animation: us-command-notice-in 180ms cubic-bezier(.2, 0, 0, 1);
  transition:
    opacity 180ms cubic-bezier(.2, 0, 0, 1),
    translate 180ms cubic-bezier(.2, 0, 0, 1);
}

.us-command-notice:empty {
  display: none;
}

/* A plain message fades out after a few seconds (US-UNIFIED-ACTIONS
   clears it); an error or a Retry offer stays until dismissed. */
.us-command-notice[data-us-leaving] {
  opacity: 0;
  translate: 0 6px;
}

@keyframes us-command-notice-in {
  from {
    opacity: 0;
    translate: 0 6px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .us-command-notice {
    animation: none;
    transition: none;
  }
}

.us-command-notice > button {
  display: inline-block;
  margin-top: 8px;
  margin-inline-end: 8px;
  padding: 4px 8px;
  background: var(--bg-subtle);
  color: var(--text-link);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
}

/* Compact actions: stronger feedback only while held, without shifting rows. */
:is(a, button):is(.TextButton, .btn).us-icon-button:active:not(:where(:disabled, [disabled], .disabled, .aspNetDisabled, [aria-disabled=true], fieldset[disabled] *)):not(:where(.us-report-no-styling, .us-report-no-styling *)),
.RadGrid.RadGrid :is(a, button):is(.TextButton, .btn).us-icon-button:active:not(:where(:disabled, [disabled], .disabled, .aspNetDisabled, [aria-disabled=true], fieldset[disabled] *)):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  border-color: currentColor;
  box-shadow: inset 0 2px 3px rgb(0 0 0 / .16);
}

@supports (background:color-mix(in srgb,white,black)) {
  :is(a, button):is(.TextButton, .btn).us-icon-button:active:not(:where(:disabled, [disabled], .disabled, .aspNetDisabled, [aria-disabled=true], fieldset[disabled] *)):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
    --button-current-bg: color-mix(in srgb,var(--button-hover-bg) 88%,var(--button-text));
  }
}

