/* US-IQA-ROW-GROUPS:START — us-iqa-row-groups on the Query Menu iPart.
   Adjacent rows sharing the first column collapse under the first row with a
   toggle. Behaviour: US-IQA-ROW-GROUPS in zUnionSuite.js. */
.us-iqa-row-groups .us-row-group__toggle:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  margin-inline-start: 8px;
  padding: 1px 7px 1px 4px;
  border: 1px solid transparent;
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--text-link);
  font: 600 11.5px/1.5 var(--font-ui);
  white-space: nowrap;
  cursor: pointer;
}

.us-iqa-row-groups .us-row-group__toggle:hover:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  border-color: var(--brand-100);
  background: var(--brand-50);
}

.us-iqa-row-groups .us-row-group__toggle:focus-visible:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  outline: 2px solid var(--border-focus);
  outline-offset: 1px;
}

.us-iqa-row-groups .us-row-group__toggle > svg {
  width: 10px;
  height: 10px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: transform 160ms;
}

.us-iqa-row-groups .us-row-group__toggle[aria-expanded="true"] > svg {
  transform: rotate(90deg);
}

/* A toggle whose hidden rows share a status badge takes that badge's tone
   (v1's red "3 failed attempts"). */
.us-iqa-row-groups .us-row-group__toggle[data-us-tone]:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  --row-group-tone: var(--text-link);
  color: var(--row-group-tone);
}

.us-iqa-row-groups .us-row-group__toggle[data-us-tone="danger"] { --row-group-tone: var(--danger); }
.us-iqa-row-groups .us-row-group__toggle[data-us-tone="warning"] { --row-group-tone: var(--warning); }
.us-iqa-row-groups .us-row-group__toggle[data-us-tone="success"] { --row-group-tone: var(--success); }
.us-iqa-row-groups .us-row-group__toggle[data-us-tone="info"] { --row-group-tone: var(--info); }

.us-iqa-row-groups .us-row-group__toggle[data-us-tone]:hover:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  border-color: color-mix(in srgb, var(--row-group-tone) 30%, transparent);
  background: color-mix(in srgb, var(--row-group-tone) 10%, transparent);
}

/* Detail rows read as one block under the parent (v1's attempt list): a
   tint, no rules between them, smaller text, a dot in place of the repeated
   key, and one tinted rule closing the group. */
.us-iqa-row-groups [data-gridid] .RadGrid tr[data-us-row-group="child"]:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  --row-group-tone: var(--border-strong);
  --row-group-tint: var(--bg-subtle);
  background-color: var(--row-group-tint);
}

.us-iqa-row-groups [data-gridid] .RadGrid tr[data-us-row-group="child"][data-us-tone="danger"] { --row-group-tone: var(--danger); --row-group-tint: var(--danger-bg); }
.us-iqa-row-groups [data-gridid] .RadGrid tr[data-us-row-group="child"][data-us-tone="warning"] { --row-group-tone: var(--warning); --row-group-tint: var(--warning-bg); }
.us-iqa-row-groups [data-gridid] .RadGrid tr[data-us-row-group="child"][data-us-tone="success"] { --row-group-tone: var(--success); --row-group-tint: var(--success-bg); }
.us-iqa-row-groups [data-gridid] .RadGrid tr[data-us-row-group="child"][data-us-tone="info"] { --row-group-tone: var(--info); --row-group-tint: var(--info-bg); }

.us-iqa-row-groups [data-gridid] .RadGrid tr[data-us-row-group="child"] > td:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  padding-block: 5px;
  border-bottom-color: transparent;
  background-color: transparent;
  font-size: 12px;
}

.us-iqa-row-groups [data-gridid] .RadGrid tr[data-us-row-group="child"][data-us-row-group-last] > td:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  border-bottom-color: color-mix(in srgb, var(--row-group-tone) 45%, transparent);
}

/* The repeated key is shown once, on the parent row; the child's cell keeps
   its text for export and screen readers but shows a dot. */
.us-iqa-row-groups [data-gridid] .RadGrid tr[data-us-row-group="child"] > td:first-child:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  position: relative;
  padding-inline-start: 24px;
  color: transparent;
}

.us-iqa-row-groups [data-gridid] .RadGrid tr[data-us-row-group="child"] > td:first-child::before {
  content: "";
  position: absolute;
  inset-inline-start: 14px;
  top: 50%;
  width: 7px;
  height: 7px;
  margin-top: -3.5px;
  border-radius: 50%;
  background: var(--row-group-tone);
}

@media (prefers-reduced-motion: reduce) {
  .us-iqa-row-groups .us-row-group__toggle > svg {
    transition: none;
  }
}

/* US-IQA-ROW-GROUPS:END */

/* US-IQA-SCROLL-EDGES:START — a report wider than its panel fades the edge
   that has columns hidden beyond it, so a clipped column no longer looks like
   the end of the table. A mask, not a shadow, because header and row cells
   paint their own backgrounds over the grid's. Behaviour:
   US-IQA-SCROLL-EDGES in zUnionSuite.js sets data-us-scroll-more. */
:is([data-gridid] .RadGrid, .RadGrid[data-gridid])[data-us-scroll-more]:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  --us-scroll-fade-start: 0px;
  --us-scroll-fade-end: 0px;
  mask-image: linear-gradient(to right,
    transparent,
    #000 var(--us-scroll-fade-start),
    #000 calc(100% - var(--us-scroll-fade-end)),
    transparent);
}

:is([data-gridid] .RadGrid, .RadGrid[data-gridid])[data-us-scroll-more~="start"] {
  --us-scroll-fade-start: 32px;
}

:is([data-gridid] .RadGrid, .RadGrid[data-gridid])[data-us-scroll-more~="end"] {
  --us-scroll-fade-end: 32px;
}

/* Right-to-left pages scroll from the right edge. */
:is([data-gridid] .RadGrid, .RadGrid[data-gridid])[data-us-scroll-more]:dir(rtl) {
  mask-image: linear-gradient(to left,
    transparent,
    #000 var(--us-scroll-fade-start),
    #000 calc(100% - var(--us-scroll-fade-end)),
    transparent);
}

/* US-IQA-SCROLL-EDGES:END */

/* US-PANEL-TONES:START — on a panel iPart's CSS class field: a tinted heading
   and a tinted border.
   - us-panel-tone-danger / -warning / -info: a fixed tone.
   - us-panel-tone-auto: the tone follows the most serious status badge in the
     panel (danger, then warning); otherwise the panel stays plain. No script.
   A toned panel with nothing in it stays plain: a native grid showing its
   empty row (rgNoRecords), or a declared Query Template (us-query-template)
   whose result set iMIS omitted. The iPart's own tokens are overridden on
   .panel, which wins over the wrapper's report token block by inheritance.
   Status tokens are remapped by zzDarkMode.css, so dark mode follows. */
.us-panel-tone-danger,
.us-panel-tone-auto:has(> .panel .us-badge--danger) {
  --us-panel-tone: var(--danger);
  --us-panel-tone-bg: var(--danger-bg);
}

.us-panel-tone-warning,
.us-panel-tone-auto:has(> .panel .us-badge--warning):not(:has(> .panel .us-badge--danger)) {
  --us-panel-tone: var(--warning);
  --us-panel-tone-bg: var(--warning-bg);
}

.us-panel-tone-info {
  --us-panel-tone: var(--info);
  --us-panel-tone-bg: var(--info-bg);
}

:is(
  .us-panel-tone-danger,
  .us-panel-tone-warning,
  .us-panel-tone-info,
  .us-panel-tone-auto:has(> .panel :is(.us-badge--danger, .us-badge--warning))
) > .panel:not(:has(.rgNoRecords)):not(.us-query-template > .panel:not(:has(.QueryTemplateSet))):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  --iqa-header: var(--us-panel-tone-bg);
  --iqa-panel-header: var(--us-panel-tone-bg);
  --iqa-border: color-mix(in srgb, var(--us-panel-tone) 35%, var(--border));
  --iqa-divider: color-mix(in srgb, var(--us-panel-tone) 25%, var(--bg-sunken));
}

/* US-PANEL-TONES:END */

/* US-PANEL-FILL:START — us-panel-fill. Opt-in per iPart (owner, 3 October
   2026). Add us-panel-fill to the iPart CSS class of each panel in a row of
   columns: the panels then stretch to the row's height, so a short panel
   leaves no gap under it. Layout rows are already flex, so the columns are
   equal; these rules let every wrapper between the column and the panel fill
   it. The iMIS path is col > .ContentItemContainer > .WebPartZone >
   .iMIS-WebPart > .ContentItemContainer > .us-panel-fill > .panel; fewer
   wrappers also work. Only wrappers inside the nearest column take part: the
   :not(:has(...)) leaves out outer wrappers (a CCO's) whose fill iPart sits
   in a deeper column. */

:is([class*="col-"], .ContentItemContainer, .WebPartZone, .iMIS-WebPart):has(.us-panel-fill):not(:has([class*="col-"] .us-panel-fill)) {
  display: flex;
  flex-direction: column;
}

:is(.ContentItemContainer, .WebPartZone, .iMIS-WebPart):has(.us-panel-fill):not(:has([class*="col-"] .us-panel-fill)),
.us-panel-fill,
.us-panel-fill > .panel {
  flex: 1 1 auto;
}

.us-panel-fill {
  display: flex;
  flex-direction: column;
}

/* A stretched panel with a card footer (US-TASK-PROGRESS) keeps the footer
   at the card's bottom edge rather than under the last row. */
.us-panel-fill > .panel:has(> .us-query-footer) {
  display: flex;
  flex-direction: column;
}

.us-panel-fill > .panel > .us-query-footer:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  margin-top: auto;
}

/* US-PANEL-FILL:END */

/* An iPart with nothing to show (the case page's Resolution on an open
   case) still renders an empty .ContentItemContainer. Its native 0.9em
   bottom margin collapses through the empty box and through the zone, so
   the whole column starts 14px below its neighbours (owner, 27 October
   2026). The page editor keeps the container, so the iPart can still be
   edited. */
body:not(.EasyEdit) .WebPartZone > .ContentItemContainer:empty {
  display: none;
}

/* US-HOME-WELCOME:START — authored Content HTML, independent of the iPart shell. */

/* iPart CSS class: iMIS creates this owner immediately around the panel.
   Override only this shell; nested iParts retain their own panel styling. */
.home-welcome-message > .panel:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}

.home-welcome-message > .panel > .panel-body-container:not(:where(.us-report-no-styling, .us-report-no-styling *)),
.home-welcome-message > .panel > .panel-body-container > .panel-body:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  padding: 0 !important;
  background: transparent !important;
}

.home-welcome:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  min-width: 0;
  margin: 0;
  color: var(--text-base);
  font: 14px/1.5 var(--font-ui);
}

.home-welcome-message .home-welcome:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  padding-inline: 20px;
}

.home-welcome > div:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  min-width: 0;
  overflow-wrap: anywhere;
}

.home-welcome > div > h1:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  font: 600 32px/1.25 var(--font-display);
  letter-spacing: -.7px;
  text-transform: none;
  margin: 0 0 5px;
  color: var(--text-strong);
  padding: 0;
  border: 0;
}

.home-welcome > div > p:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  font-size: 15px;
  margin: 0;
  color: var(--text-muted);
}

.home-welcome > .home-welcome-date:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  font-size: 14px;
  color: var(--text-muted);
}

@media (max-width:900px) {
  .home-welcome > .home-welcome-date:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
    display: none;
  }
}

@media (max-width:600px) {
  .home-welcome > div > h1:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
    font-size: 27px;
  }
