}

.us-query-filter-fields {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
}

.us-query-filter-fields > .us-query-search-field {
  flex: 1 1 100%;
  width: 100%;
  max-width: none;
}

.us-query-search-field:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
