  width: 17px;
  height: 17px;
  pointer-events: none;
}

[data-us-query-display] .us-query-search-field input[type="search"]:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  box-sizing: border-box;
  flex: 1;
