  min-height: 2.5rem;
  margin: 0;
  padding: var(--space-2) var(--space-3);
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--banner-menu-text);
  font: inherit;
  font-size: var(--fs-sm);
  text-align: start;
  text-decoration: none;
  white-space: normal;
  cursor: pointer;
}

.us-banner .us-banner__surface .us-banner__menu-item:hover:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  background: var(--banner-menu-hover);
}

.us-banner .us-banner__surface .us-banner__menu-item:focus-visible:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  outline: 2px solid var(--border-focus);
  outline-offset: -2px;
}

.us-banner .us-banner__surface .us-banner__menu-item--danger:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
