}

.us-banner .us-banner__nav:has(> .us-banner__tabs):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: block;
  padding-top: 0;
  transition: margin-top var(--banner-motion-duration) var(--banner-motion-easing);
}

.us-banner .us-banner__tabs:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: flex;
  flex-wrap: nowrap;
  gap: var(--space-1);
  max-width: 100%;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  scrollbar-width: thin;
  scrollbar-color: var(--banner-border) var(--banner-bg);
}

.us-banner .us-banner__surface .us-banner__tab:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  min-height: 2.75rem;
  margin: 0;
  padding: var(--space-3) var(--space-4);
  border: 0;
  border-bottom: 2px solid transparent;
  border-radius: 0;
  background: transparent;
  color: var(--banner-text);
  font: inherit;
  font-size: var(--fs-sm);
  font-weight: var(--fw-medium);
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
}

.us-banner .us-banner__surface .us-banner__tab:hover:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
