  border-bottom-color: var(--banner-accent);
  font-weight: var(--fw-bold);
}

.us-banner .us-banner__surface .us-banner__tab:focus-visible:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  outline: 2px solid var(--banner-text);
  outline-offset: -4px;
}

.us-banner .us-banner__surface .us-banner__tab:disabled:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  cursor: default;
  opacity: .75;
}

.us-banner .us-banner__surface .us-banner__tab.is-active:disabled:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  opacity: 1;
}

@media (max-width: 600px) {
  .us-banner .us-banner__surface:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
