  }

  .us-banner .us-banner__status:not(:where(.us-report-no-styling, .us-report-no-styling *)),
  .us-banner .us-banner__actions:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
    flex-basis: 100%;
  }
}

/* TWO-TIER BEHAVIOUR — classes below are managed by the final script.
   Keep the original nodes inside their iPart; a measured slot follows the
   animated surface height. Native header/nav and dialogs remain above it. */
body:has(.us-banner--enhanced):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  overflow-anchor: none;
}

.us-banner.us-banner--enhanced .us-banner__surface:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  transition: padding-block var(--banner-motion-duration) var(--banner-motion-easing);
}

.us-banner.us-banner--pinned .us-banner__surface:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  position: fixed;
  top: var(--us-banner-fixed-top);
  left: var(--us-banner-fixed-left);
  width: var(--us-banner-fixed-width);
  z-index: calc(var(--z-sidebar) - 1);
}

.us-banner.us-banner--enhanced .us-banner__title:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  transition: font-size var(--banner-motion-duration) var(--banner-motion-easing);
}

.us-banner.us-banner--enhanced .us-banner__avatar:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  transition: width var(--banner-motion-duration) var(--banner-motion-easing),
    height var(--banner-motion-duration) var(--banner-motion-easing),
    font-size var(--banner-motion-duration) var(--banner-motion-easing);
}

.us-banner .us-banner__fold:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: grid;
  grid-template-rows: 1fr;
  opacity: 1;
  transition: grid-template-rows var(--banner-motion-duration) var(--banner-motion-easing),
    opacity var(--banner-motion-duration) var(--banner-motion-easing);
}

.us-banner .us-banner__fold-inner:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  min-height: 0;
  overflow: hidden;
}

.us-banner.us-banner--compact .us-banner__surface:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  padding-block: var(--space-2);
}

.us-banner.us-banner--compact .us-banner__title:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  font-size: var(--fs-lg);
}

.us-banner.us-banner--compact .us-banner__avatar:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  width: 32px;
  height: 32px;
  font-size: var(--fs-sm);
}

.us-banner.us-banner--compact .us-banner__fold:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  grid-template-rows: 0fr;
  opacity: 0;
}

.us-banner.us-banner--compact .us-banner__nav:has(> .us-banner__tabs):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
