:root .us-banner .us-banner__surface:is(.us-banner__surface--member, .us-banner__surface--glass)[class]:not(:where(.us-report-no-styling *)) .us-actions > .us-actions__toggle:not(:disabled):is(:hover, :focus-visible, [aria-expanded=true]) {
