  box-shadow: inset 0 1px 0 rgb(255 255 255 / 48%),inset 0 -1px 0 rgb(255 255 255 / 12%),0 3px 10px rgb(0 20 30 / 20%),0 0 14px rgb(200 239 255 / 15%);
