  .SearchContactsClass *,
  [data-us-iqa-native] *,
  .RadGrid *,
  .RadComboBox *,
  .RadInput *,
  .RadPicker *,
  .RadEditor *,
  .RadSplitter *,
  .RadUpload *,
  .RadAsyncUpload *,
  .chosen-container *
)):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
