  float: none;
  width: 100%;
  min-width: 0;
  padding: 0;
}

.us-form .PanelFieldValue > :is(
  input:not([type=checkbox], [type=radio], [type=button], [type=submit], [type=reset], [type=hidden], [type=image]),
