  font: 13px/1.5 var(--font-ui);
  box-shadow: none;
}

.us-form .PanelFieldValue > :is(
  input:not([type=checkbox], [type=radio], [type=button], [type=submit], [type=reset], [type=hidden], [type=image]),
  select,
  textarea
):not(:where(
  .us-report *,
  .SearchContactsClass *,
  [data-us-iqa-native] *,
  .RadGrid *,
  .RadComboBox *,
  .RadInput *,
  .RadPicker *,
  .RadEditor *,
  .RadSplitter *,
  .RadUpload *,
