/* US-SECTION-LOADING:START — selected circles and native Telerik presentation */
.section-loader-spinning-circles:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  --color-1: var(--brand-600);
  --color-2: var(--accent);
  --size: 1px;
  width: calc(48 * var(--size));
  height: calc(48 * var(--size));
  border-radius: 50%;
  display: inline-block;
  position: relative;
  flex: none;
  border: calc(3 * var(--size)) solid;
  border-color: var(--color-1) var(--color-1) transparent transparent;
  box-sizing: border-box;
  animation: section-circles-forward 1.428571s linear infinite;
}

.section-loader-spinning-circles:not(:where(.us-report-no-styling, .us-report-no-styling *))::after,
.section-loader-spinning-circles:not(:where(.us-report-no-styling, .us-report-no-styling *))::before {
  content: '';
  box-sizing: border-box;
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;
  margin: auto;
  border: calc(3 * var(--size)) solid;
  border-color: transparent transparent var(--color-2) var(--color-2);
  width: calc(40 * var(--size));
  height: calc(40 * var(--size));
  border-radius: 50%;
  animation: section-circles-back .714286s linear infinite;
  transform-origin: center center;
}

.section-loader-spinning-circles:not(:where(.us-report-no-styling, .us-report-no-styling *))::before {
  width: calc(32 * var(--size));
  height: calc(32 * var(--size));
  border-color: var(--color-1) var(--color-1) transparent transparent;
  animation: section-circles-forward 2.142857s linear infinite;
}

@keyframes section-circles-forward {
  0% {
    transform: rotate(0deg);
  }

  100% {
    transform: rotate(360deg);
  }
}

@keyframes section-circles-back {
  0% {
    transform: rotate(0deg);
  }

  100% {
    transform: rotate(-360deg);
  }
}

@media (prefers-reduced-motion:reduce) {
  .section-loader-spinning-circles:not(:where(.us-report-no-styling, .us-report-no-styling *)),
  .section-loader-spinning-circles:not(:where(.us-report-no-styling, .us-report-no-styling *))::before,
  .section-loader-spinning-circles:not(:where(.us-report-no-styling, .us-report-no-styling *))::after {
    animation: none;
  }
}

/* A popup's content cell is a host while Telerik marks it rwLoading and
   while its frame loads a page (data-us-frame-loading, set by the theme).
   The theme dialog's body is a host while its page loads (data-us-loading). */
:is(.rwWindowContent, .rwContent, .us-dialog__body).us-native-loader-host:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  position: relative;
}

.us-native-loader-host:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  background-image: none !important;
}

.us-native-loader-host > .us-native-section-spinner:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  position: absolute;
  left: 50%;
  top: 50%;
  margin: -24px 0 0 -24px;
  pointer-events: none;
  z-index: 1;
  opacity: 1;
  transition: opacity 180ms cubic-bezier(.2, 0, 0, 1);
}

@starting-style {
