}

.us-native-loader-ripples > span:nth-child(3):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  --us-ripple-strength: 30%;
  animation-delay: 2.36s;
}

/* Each ripple leaves as the rings stretch (26%) and fades out by 72%. */
@keyframes us-popup-loader-ripple {
  0%,
  24% {
    outline-offset: 0;
    outline-color: transparent;
  }

  26% {
    outline-offset: 0;
    outline-color: color-mix(in srgb, var(--accent) var(--us-ripple-strength), transparent);
    animation-timing-function: cubic-bezier(.2, 0, .2, 1);
  }

  72% {
    outline-offset: 40px;
    outline-color: transparent;
  }

  72.01%,
  100% {
    outline-offset: 0;
    outline-color: transparent;
  }
}

/* The shared rule stops the spin; the popup's own lists need stopping too. */
@media (prefers-reduced-motion: reduce) {
  :is(.rwWindowContent, .rwContent, .us-dialog__body).us-native-loader-host > .us-native-section-spinner:not(:where(.us-report-no-styling, .us-report-no-styling *)),
