:is([id^="formrender_"]:not(.rendered-form *), [data-beyondformid]).us-native-loader-host > .us-native-section-spinner:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  top: 36px;
  margin-top: 0;
}

/* Rendering clears the placeholder, spinner and all, and a form still
   loading gets a new one at once: no fade-in, so it does not blink. */
@starting-style {
  :is([id^="formrender_"]:not(.rendered-form *), [data-beyondformid]).us-native-loader-host > .us-native-section-spinner:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
    opacity: 1;
