/* US-IQA-REFRESH-OVERLAY:START */
.us-iqa-refresh-overlay:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  position: fixed;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255,255,255,.78);
  background: color-mix(in srgb,var(--bg-surface) 78%,transparent);
  z-index: var(--z-tooltip,100000);
  cursor: progress;
}

.us-iqa-refresh-overlay[hidden]:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: none;
}

.us-iqa-refresh-status:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  border: 0;
  clip-path: inset(50%);
  overflow: hidden;
  white-space: nowrap;
}

.us-iqa-find-overlay {
  position: fixed;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255,255,255,.72);
  background: color-mix(in srgb,var(--bg-surface) 72%,transparent);
  z-index: var(--z-tooltip,100000);
  cursor: progress;
}

.us-iqa-find-overlay[hidden] {
  display: none;
}

/* Row expand/collapse: the shared spinner takes the clicked arrow's place,
   sized to it by US-IQA-BUSY. The overlay catches a second click; the native
   control keeps focus and handlers, with only its glyph hidden. */
.us-iqa-row-spinner {
  position: fixed;
  z-index: var(--z-tooltip,100000);
  overflow: hidden;
  cursor: progress;
  animation: us-iqa-row-fade-in 140ms ease-out;
}

.us-iqa-row-spinner[hidden] {
  display: none;
}

.us-iqa-row-spinner > .section-loader-spinning-circles {
  position: absolute;
}

.rgExpandCol [data-us-iqa-row-busy] {
  opacity: 0 !important;
  transition: opacity 140ms ease-out;
}

/* The new detail row slides open (or a copy of the old one closed) after the
   native partial update; fold() animates this box, which carries the
   cell's vertical padding meanwhile. */
tr[data-us-iqa-detail-sliding] > td {
  padding-top: 0 !important;
  padding-bottom: 0 !important;
}

.us-iqa-detail-slide[hidden] {
  display: none;
}

/* Detail rows sit out of column fitting for the frame after a row update. */
tr[data-us-iqa-detail-hold] {
  display: none !important;
}

/* Query Template refresh retains the visible records below this overlay. */
.us-query-refresh-overlay {
  position: absolute;
  inset: 0;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: inherit;
  background: color-mix(in srgb, var(--bg-surface) 55%, transparent);
  cursor: progress;
}

.us-query-refresh-overlay > .section-loader-spinning-circles {
  --size: .5px;
}

/* A single row refreshing in place (reloadRow, US-ROW-PATCH): the theme's
   loader over the row, on a light veil; the rest of the list stays usable. */
.us-row-refreshing {
  pointer-events: none;
  cursor: progress;
}

.us-row-refresh-surface {
  position: relative;
}

.us-row-refresh-overlay {
  position: absolute;
  inset: 0;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: inherit;
  background: color-mix(in srgb, var(--bg-surface) 60%, transparent);
}

.us-row-refresh-overlay > .section-loader-spinning-circles {
  --size: .5px;
}

@keyframes us-iqa-row-fade-in {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@media (prefers-reduced-motion:reduce) {
  .us-iqa-row-spinner {
    animation: none;
  }

  .rgExpandCol [data-us-iqa-row-busy] {
    transition: none;
  }
}

[data-us-iqa-progress-replaced] {
  display: none !important;
}

