/* US-TASKBAR-COMPONENT:START */

/* Hide the native search block (kept in DOM — other iMIS scripts
   reference #ctl01_SearchFieldPlus_Shortcuts_RadAjaxPanel1) */
html.us-taskbar-mounted #hd .searchfieldplus-dropdown {
  display: none !important;
}

/* #5: hide the redundant native mobile search toggle */
html.us-taskbar-mounted #hd .search-dropdown {
  display: none !important;
}

#injected-taskbar {
  --bg: #f4f6f9;
  --surface: #ffffff;
  --border: #dde1e7;
  --text: #1a1f2e;
  --text-muted: #6b7280;
  --primary: #2563eb;
  --primary-hover: #1d4ed8;
  --selected-bg: #eff6ff;
  --shadow-md: 0 4px 12px rgba(0,0,0,.1);
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 14px;
  color: var(--text);
  box-sizing: border-box;
  min-width: 0;
}

#injected-taskbar label {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-muted);
  white-space: nowrap;
}

#injected-taskbar .tb-id-wrap,
#injected-taskbar .tb-id-fields,
#injected-taskbar .tb-search-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

#injected-taskbar .tb-id-fields,
#injected-taskbar .tb-search-wrap {
  position: relative;
}

#injected-taskbar .tb-id-status {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  white-space: nowrap;
  font-size: 12px;
  font-weight: 600;
  padding: 4px 8px;
  border-radius: 6px;
  z-index: 10000;
}

#injected-taskbar .tb-id-status.error {
  color: #dc2626;
  background: #fee2e2;
}

#injected-taskbar .tb-btn:disabled {
  background: #cbd5e1;
  cursor: not-allowed;
}

#injected-taskbar .tb-divider {
  width: 1px;
  height: 20px;
  background: var(--border);
  margin: 0 4px;
  flex-shrink: 0;
}

#injected-taskbar .tb-input,
#injected-taskbar .tb-search-input {
  padding: 6px 10px;
  border: 1.5px solid var(--border);
  border-radius: 8px;
  font-size: 14px;
  outline: none;
  background: var(--bg);
  color: var(--text);
  min-width: 0;
  transition: border-color .15s;
  font-family: inherit;
}

#injected-taskbar .tb-input {
  box-sizing: border-box;
  width: 96px;
}

#injected-taskbar .us-taskbar__search-icon {
  flex: 0 0 18px;
  width: 18px;
  height: 18px;
  fill: none;
  stroke: var(--text-muted);
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

#injected-taskbar .tb-search-input {
  width: 180px;
}

#injected-taskbar .tb-input:focus,
#injected-taskbar .tb-search-input:focus {
  border-color: var(--primary);
  background: #fff;
}

#injected-taskbar .tb-btn {
  padding: 6px 16px;
  border-radius: 7px;
  border: none;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  font-family: inherit;
  background: var(--primary);
  color: #fff;
  transition: background .15s, transform .1s;
}

#injected-taskbar .tb-btn:hover {
  background: var(--primary-hover);
}

#injected-taskbar .tb-btn:active {
  transform: scale(.97);
}

/* Search dropdown */
#tb-search-dropdown {
  position: absolute;
  top: calc(100% + 4px);
  right: 0;
  min-width: 320px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  box-shadow: var(--shadow-md);
  z-index: 10000;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --text: #1a1f2e;
  --text-muted: #6b7280;
  --border: #dde1e7;
  --primary: #2563eb;
  --selected-bg: #eff6ff;
  --bg: #f4f6f9;
}

#tb-search-dropdown .tb-dd-header {
  display: none;
}

#tb-search-dropdown .tb-dd-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 10px 14px 10px 10px;
  cursor: pointer;
  border-bottom: 1px solid var(--border);
  text-decoration: none;
  color: var(--text);
  transition: background .1s;
}

#tb-search-dropdown .tb-dd-item:last-child {
  border-bottom: none;
}

#tb-search-dropdown .tb-dd-item:hover {
  background: var(--selected-bg);
}

#tb-search-dropdown .tb-dd-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text);
  flex: 1;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

#tb-search-dropdown .tb-dd-id {
  font-size: 11px;
  font-weight: 600;
  color: var(--primary);
  background: var(--selected-bg);
  padding: 2px 8px;
  border-radius: 4px;
  white-space: nowrap;
  flex-shrink: 0;
}

#tb-search-dropdown .tb-dd-meta {
  font-size: 11px;
  color: var(--text-muted);
  margin-top: 1px;
}

#tb-search-dropdown .tb-dd-match {
  font-size: 11px;
  color: var(--text-muted);
  margin-top: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

#tb-search-dropdown .tb-dd-match strong {
  color: var(--text);
  font-weight: 700;
  background: #fef9c3;
  border-radius: 2px;
  padding: 0 1px;
}

#tb-search-dropdown .tb-dd-msg {
  padding: 12px 14px;
  font-size: 13px;
  color: var(--text-muted);
  text-align: center;
}

#tb-search-dropdown .tb-dd-section {
  padding: 8px 14px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .04em;
  color: var(--text-muted);
  background: var(--bg);
  border-bottom: 1px solid var(--border);
}

/* ── Responsive ─────────────────────────────────── */

/* <=1200px: labels cost the most horizontal space */
@media (max-width: 1200px) {
  #injected-taskbar label {
    display: none;
  }
}

/* <=992px: shrink the inputs */
@media (max-width: 992px) {
  #injected-taskbar .tb-input {
    width: 84px;
  }

  #injected-taskbar .tb-search-input {
    width: 130px;
  }
}

/* <=768px: drop the iMIS-ID field; keep quick search; results go full screen */
@media (max-width: 768px) {
  #injected-taskbar .tb-id-wrap,
  #injected-taskbar .tb-divider {
    display: none;
  }

  #injected-taskbar .tb-search-input {
    width: 150px;
  }

  #tb-search-dropdown {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    width: 100vw;
    height: 100vh;
    height: 100dvh;
    min-width: 0;
    border: none;
    border-radius: 0;
    box-shadow: none;
    z-index: 100000;
    display: flex;
    flex-direction: column;
  }

  #tb-search-dropdown .tb-dd-header {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 12px 14px;
    border-bottom: 1px solid var(--border);
    background: var(--surface);
    flex-shrink: 0;
  }

  #tb-search-dropdown .tb-dd-input {
    flex: 1;
    min-width: 0;
    padding: 10px 12px;
    border: 1.5px solid var(--border);
    border-radius: 8px;
    font-size: 16px; /* 16px keeps iOS from zooming on focus */
    outline: none;
    background: var(--bg);
    color: var(--text);
    font-family: inherit;
  }

  #tb-search-dropdown .tb-dd-input:focus {
    border-color: var(--primary);
    background: #fff;
  }

  #tb-search-dropdown .tb-dd-close {
    border: none;
    background: none;
    font-size: 24px;
    line-height: 1;
    cursor: pointer;
    color: var(--text-muted);
    padding: 4px 6px;
    flex-shrink: 0;
  }

  #tb-search-dropdown .tb-dd-body {
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
  }
}

#injected-taskbar [hidden],
#tb-search-dropdown[hidden] {
  display: none !important;
}

.us-taskbar__result-info {
  min-width: 0;
  flex: 1;
}

.us-taskbar__result-kind {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 18px;
  width: 18px;
  height: 24px;
  color: var(--brand-600);
}

/* The icon is a theme icon (us-building, us-person; US-ICONS), drawn a
   little lighter than Tabler's default at this size. */
.us-taskbar__result-kind .us-icon {
  display: block;
  font-size: 18px;
  --us-icon-stroke: 1.7;
}

/* US-TASKBAR-COMPONENT:END */

/* US-TASKBAR-COLOURS:START — existing injection owns layout and behaviour.
   Root specificity wins over its ID-only embedded fallback styles. */
:root #injected-taskbar,
:root #tb-search-dropdown {
  --primary: var(--accent);
  --primary-hover: var(--accent-hover);
  --selected-bg: var(--accent-100);
}

:root #injected-taskbar .tb-btn {
  color: var(--text-on-accent);
}

:root #injected-taskbar .tb-btn:hover:not(:disabled) {
  background: var(--accent-100);
  color: var(--brand-900);
  box-shadow: inset 0 0 0 1px var(--accent);
}

:root #injected-taskbar .tb-btn:active:not(:disabled) {
  background: var(--accent-100);
  color: var(--brand-900);
  transform: none;
  box-shadow: inset 0 2px 4px rgb(0 0 0 / .24),inset 0 0 0 1px var(--accent);
}

:root #injected-taskbar .tb-btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

:root #injected-taskbar .tb-btn:disabled {
  background: var(--neutral-300);
  color: var(--text-muted);
}

:root #injected-taskbar :is(.tb-input, .tb-search-input):focus {
  border-color: var(--border-focus);
}

:root #tb-search-dropdown .tb-dd-id {
  background: var(--accent-100);
  color: var(--brand-900);
}

:root #tb-search-dropdown .tb-dd-match strong {
  background: var(--accent-100);
  color: var(--brand-900);
}

:root #tb-search-dropdown .tb-dd-item:focus-visible {
  background: var(--accent-100);
  outline: 2px solid var(--border-focus);
  outline-offset: -2px;
}

/* US-TASKBAR-COLOURS:END */

/* US-NATIVE-TABS-PAGE-LAYOUT:START */

/* Rail width and the card-style gap (contact page v3, item 5). */
:root {
  --us-cco-rail-width: 220px;
  --us-cco-cards-gap: var(--space-5);
}

:root .tabs-wrapper.tabs-vertical {
  display: grid;
  grid-template-columns: var(--us-cco-rail-width) minmax(0, 1fr);
  gap: 0;
  align-items: stretch;
}

:root .tabs-wrapper.tabs-vertical > .RadTabStripVertical {
  grid-column: 1;
  grid-row: 1;
  align-self: stretch;
}

:root .tabs-wrapper.tabs-vertical > .RadMultiPage {
  grid-column: 2;
  grid-row: 1;
  min-width: 0;
  padding: 18px 24px;
}

@media (max-width:600px) {
  :root .tabs-wrapper.tabs-vertical {
    display: block;
  }

  :root .tabs-wrapper.tabs-vertical > .RadMultiPage {
    padding: 18px;
  }
}

/* The CCO iPart's "Tab display style: Vertical right" (iMIS renders
   .tabs-right on the .cco element and RadTabStripRight on the strip, in the
   same markup order as "Vertical left"): the strip takes the right-hand
   column on desktop. Phones keep the stacked tabs. */
@media (min-width: 601px) {
  :root .tabs-wrapper.tabs-vertical.tabs-right {
    grid-template-columns: minmax(0, 1fr) var(--us-cco-rail-width);
  }

  :root .tabs-wrapper.tabs-vertical.tabs-right > .RadTabStripVertical {
    grid-column: 2;
  }

  :root .tabs-wrapper.tabs-vertical.tabs-right > .RadMultiPage {
    grid-column: 1;
  }
}

/* US-NATIVE-TABS-PAGE-LAYOUT:END */

/* US-NATIVE-TABS-COMPONENT:START */
:root :is(.RadTabStrip, .RadTabStripVertical) {
  --rail-bg: transparent;
  --rail-border: transparent;
  --rail-radius: 0px;
  --rail-pad: 6px;
  --tab-bg: transparent;
  --tab-color: var(--text-base);
  --tab-border: transparent;
  --tab-radius: 6px;
  --tab-gap: 4px;
  --tab-pad: 10px 16px;
  --tab-height: 40px;
  --active-bg: var(--accent);
  --active-color: var(--text-on-accent);
  --active-border: var(--accent);
  --active-shadow: none;
  --hover-bg: var(--accent-100);
  --hover-color: var(--brand-900);
  --hover-border: transparent;
  --focus-color: var(--border-focus);
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  min-width: 0;
  background: var(--rail-bg);
  border: 1px solid var(--rail-border);
  border-radius: var(--rail-radius);
}

:root :is(.RadTabStrip, .RadTabStripVertical) > .rtsLevel {
  width: auto;
  padding: var(--rail-pad);
  border: 0;
  height: auto;
}

:root :is(.RadTabStrip, .RadTabStripVertical) > .rtsLevel > .rtsUL {
  display: flex;
  flex-wrap: wrap;
  gap: var(--tab-gap);
  float: none;
  width: auto;
  margin: 0;
  padding: 0;
  list-style: none;
}

:root :is(.RadTabStrip, .RadTabStripVertical) > .rtsLevel > .rtsUL::after {
  display: none;
}

:root :is(.RadTabStrip, .RadTabStripVertical) > .rtsLevel > .rtsUL > .rtsLI {
  display: block;
  flex: 0 0 auto;
  float: none;
  margin: 0;
  padding: 0;
}

:root :is(.RadTabStrip, .RadTabStripVertical) > .rtsLevel > .rtsUL > .rtsLI > .rtsLink {
  box-sizing: border-box;
  position: relative;
  display: flex;
  align-items: center;
  float: none;
  width: auto;
  min-height: var(--tab-height);
  margin: 0;
  padding: var(--tab-pad);
  border: 1px solid var(--tab-border);
  border-radius: var(--tab-radius);
  background: var(--tab-bg);
  color: var(--tab-color);
  font: var(--fw-semi) 13px/1.5 var(--font-ui);
  text-align: left;
  white-space: nowrap;
  text-decoration: none;
  box-shadow: none;
  cursor: pointer;
}

:root :is(.RadTabStrip, .RadTabStripVertical) > .rtsLevel > .rtsUL > .rtsLI > .rtsLink :is(.rtsOut, .rtsIn, .rtsTxt) {
  display: block;
  float: none;
  padding: 0;
  background: none;
  line-height: inherit;
  text-align: inherit;
}

:root :is(.RadTabStrip, .RadTabStripVertical) > .rtsLevel > .rtsUL > .rtsLI > .rtsLink:hover {
  background: var(--hover-bg);
  border-color: var(--hover-border);
  color: var(--hover-color);
}

:root :is(.RadTabStrip, .RadTabStripVertical) > .rtsLevel > .rtsUL > .rtsLI > .rtsLink.rtsSelected {
  background: var(--active-bg);
  border-width: 1px;
  border-color: var(--active-border);
  color: var(--active-color);
  box-shadow: var(--active-shadow);
}

:root :is(.RadTabStrip, .RadTabStripVertical) > .rtsLevel > .rtsUL > .rtsLI > .rtsLink:active:not(:where(.rtsDisabled, [aria-disabled="true"])) {
  box-shadow: inset 0 2px 4px rgb(0 0 0 / .24), inset 0 0 0 100vmax rgb(0 0 0 / .06);
}

/* Native link focus can outlast a mouse click. Reserve the outline for
   keyboard focus; :active supplies the momentary depressed presentation. */
:root :is(.RadTabStrip, .RadTabStripVertical) > .rtsLevel > .rtsUL > .rtsLI > .rtsLink:focus:not(:focus-visible) {
  outline: none;
}

:root :is(.RadTabStrip, .RadTabStripVertical) > .rtsLevel > .rtsUL > .rtsLI > .rtsLink:focus-visible {
  outline: 2px solid var(--focus-color);
  outline-offset: -4px;
}

:root :is(.RadTabStrip, .RadTabStripVertical) > .rtsLevel > .rtsUL > .rtsLI > .rtsLink:is(.rtsDisabled, [aria-disabled="true"]) {
  opacity: .45;
  cursor: not-allowed;
  background: var(--tab-bg);
  color: var(--tab-color);
  border-color: var(--tab-border);
  box-shadow: none;
}

/* Horizontal 2: attached folder tabs with a strong accent cap. */
:root .RadTabStrip {
  --rail-pad: 4px 0 0;
  --tab-gap: 3px;
  --tab-radius: 7px 7px 0 0;
  --tab-bg: var(--bg-sunken);
  --tab-border: var(--border);
  --tab-pad: 10px 16px;
  --active-bg: var(--bg-surface);
  --active-color: var(--brand-900);
  --active-border: var(--border);
  --active-shadow: inset 0 4px 0 var(--accent);
  --hover-bg: var(--accent-100);
  --hover-border: var(--accent);
  border-inline-width: 0;
  border-bottom-color: var(--border);
}

:root .RadTabStrip > .rtsLevel > .rtsUL > .rtsLI > .rtsLink.rtsSelected:hover:not(:where(.rtsDisabled, [aria-disabled="true"])) {
  border-color: var(--accent);
  border-bottom-color: var(--bg-surface);
}

:root .RadTabStrip + .RadMultiPage {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-top: 0;
  padding: 16px;
}

:root .RadTabStrip > .rtsLevel > .rtsUL > .rtsLI > .rtsLink.rtsSelected {
  border-bottom-color: var(--bg-surface);
  margin-bottom: 0;
  padding-bottom: 11px;
  z-index: 1;
}

/* Move the entire level across the rail border; a negative flex-item margin
   alone also shrinks the list, leaving the border below the selected tab. */
:root .RadTabStrip > .rtsLevel {
  margin-bottom: -1px;
  position: relative;
}

:root[data-us-tabs-pointer] :is(.RadTabStrip, .RadTabStripVertical) > .rtsLevel > .rtsUL > .rtsLI > .rtsLink:focus {
  outline: none;
}

/* A query with no rendered filter panel has no separator below the selector. */
:is(.us-report, .SearchContactsClass, [data-us-iqa-native]) [id$="_ContentPanel"]:not(:has(> [id$="_ListerPanel"] > [data-gridid] > :is(.FilterPanel, .FilterPanelHorizontal))) > .ClearFix > [id$="_SelectContainer"]:has(> select[id$="_querySelectDropdown"]):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  border-bottom-width: 0;
}

/* Native Telerik levels can float and shrink to the longest label. Fill the
   rail so the selected tab's open edge meets the adjoining content panel. */
:root .RadTabStripVertical > .rtsLevel {
  box-sizing: border-box;
  float: none;
  width: 100%;
  height: 100%;
}

:root .RadTabStripVertical.RadTabStrip_Orion > .rtsLevel.rtsLevel1 {
  border: 0;
}

:root .RadTabStripVertical > .rtsLevel > .rtsUL {
  flex-direction: column;
  flex-wrap: nowrap;
}

:root .RadTabStripVertical > .rtsLevel > .rtsUL > .rtsLI > .rtsLink {
  width: 100%;
  white-space: normal;
  overflow-wrap: anywhere;
}

@media (min-width: 601px) {
  :root .RadTabStripVertical > .rtsLevel > .rtsUL {
    width: 100%;
    align-items: stretch;
  }

  :root .RadTabStripVertical > .rtsLevel > .rtsUL > .rtsLI {
    width: 100%;
    box-sizing: border-box;
  }
}

/* Approved V5: open-right selection, short accent fade and white panel. */
:root {
  --open-surface: var(--bg-surface);
  --open-border: var(--border);
}

:root .RadTabStripVertical {
  --rail-pad: 4px 0 4px 4px;
  --tab-gap: 4px;
  --tab-radius: 7px 0 0 7px;
  --tab-bg: var(--bg-sunken);
  --tab-border: var(--open-border);
  --tab-pad: 10px 16px;
  --active-bg: var(--open-surface);
  --active-color: var(--brand-900);
  --active-border: var(--open-border);
  --active-shadow: inset 4px 0 0 var(--accent);
  --hover-bg: var(--accent-100);
  border: 0;
  border-right: 1px solid var(--open-border);
}

:root .RadTabStripVertical + .RadMultiPage {
  background: var(--open-surface);
  border: 1px solid var(--open-border);
  border-left: 0;
}

:root .RadTabStripVertical > .rtsLevel > .rtsUL > .rtsLI > .rtsLink.rtsSelected {
  width: calc(100% + 1px);
  margin-right: -1px;
  border-right-color: var(--open-surface);
  z-index: 1;
}

/* V5: V2's grey menu, white inactive rows and warm accent selected state,
   using V4's attached shape. The selected fill fades into a white panel. */
:root .RadTabStripVertical {
  --rail-bg: var(--bg-sunken);
  --tab-bg: var(--bg-surface);
  --tab-border: var(--border);
  --fade-direction: to right;
  --active-bg: linear-gradient(var(--fade-direction), var(--accent-100) 0%, var(--accent-100) 78%, var(--bg-surface) 100%);
  --active-border: var(--accent);
  --hover-bg: var(--accent-100);
  --hover-border: var(--accent);
}

.us-tab-sections {
  display: none;
}

@media (max-width: 600px) {
  :root .RadTabStripVertical {
    --active-bg: var(--accent-100);
  }

  :root :is(.RadTabStrip, .RadTabStripVertical) {
    --tab-height: 44px;
  }

  :root .RadTabStrip > .rtsLevel {
    overflow-x: auto;
