  :root :is(.RadTabStrip, .RadTabStripVertical) > .rtsLevel[data-more-left="true"][data-more-right="true"] {
    mask-image: linear-gradient(to right, transparent, #000 16px, #000 calc(100% - 16px), transparent);
  }

  :root .us-tab-sections {
    display: block;
    position: relative;
    z-index: 5;
    margin: 0 4px 6px;
    color: var(--text-base);
  }

  .us-tab-sections summary {
    display: flex;
