  :root :is(.us-cco-cards, .us-cco-rail) :is(.cco, .tabs-wrapper).tabs-vertical:not(:where(:is(.us-cco-cards, .us-cco-rail) :is(.cco, .tabs-wrapper) :is(.cco, .tabs-wrapper), .us-report-no-styling, .us-report-no-styling *)) {
