  :root :is(.us-cco-collapsible, .us-cco-rail) :is(.cco, .tabs-wrapper).tabs-vertical.tabs-right[data-us-cco-rail="collapsed"][data-us-cco-sections-inline] > .RadMultiPage > .rmpView [data-us-cco-sections-host] {
