/* Collapse/expand duration: one setting for the script and these rules. */
:root {
  --us-cco-rail-motion: 1000ms;
}

/* Collapse/expand motion: the view transition started by the rail script.
   Only active while data-us-cco-rail-transition is on the root. The rail
   morphs to or from the Sections box in two steps (see the script). */
:root[data-us-cco-rail-transition]::view-transition-group(*),
:root[data-us-cco-rail-transition]::view-transition-old(*),
:root[data-us-cco-rail-transition]::view-transition-new(*) {
  /* --us-cco-rail-motion is also read by US-CCO-RAIL-COLLAPSE; the rail's own two-step
     keyframes are applied by script on top of these defaults. */
  animation-duration: var(--us-cco-rail-motion);
  animation-timing-function: cubic-bezier(.4, 0, .2, 1);
}

/* Keep each snapshot's own proportions while its box resizes. */
:root[data-us-cco-rail-transition]::view-transition-old(*),
:root[data-us-cco-rail-transition]::view-transition-new(*) {
  height: 100%;
  object-fit: none;
  object-position: left top;
}

/* Clip each snapshot to its morphing box: the menu folds up without its full
   height spilling below, and the content is revealed as its box resizes. */
/* Only the menu is a snapshot: the page itself is not captured, so the
   content stays live and animates its real layout (see the rail script).
   The menu's snapshots are clipped to the morphing box. */
:root[data-us-cco-rail-transition] {
  view-transition-name: none;
}

/* Held content blocks must not trigger scroll anchoring mid-animation (the
   page jumped, often to the bottom). The script also restores the scroll. */
:root[data-us-cco-rail-transition],
:root[data-us-cco-rail-transition] body {
  overflow-anchor: none;
}

:root[data-us-cco-rail-transition]::view-transition-group(*) {
  overflow: clip;
}

/* The snapshot layer sits above the whole page, including a pinned banner.
   Clip it below the page chrome (--us-cco-rail-clip-top, set by the rail
   script) so the menu stays beneath the banner, as it does outside the
   animation. */
:root[data-us-cco-rail-transition]::view-transition {
  clip-path: inset(var(--us-cco-rail-clip-top, 0px) 0 0 0);
}

/* A right-hand rail's snapshots stay pinned to the right edge, so the rail
   folds towards its own side instead of appearing to come from the left.
   The content keeps its left anchor in both cases. */
:root[data-us-cco-rail-transition="right"]::view-transition-old(us-cco-rail),
:root[data-us-cco-rail-transition="right"]::view-transition-new(us-cco-rail) {
  object-position: right top;
}

/* US-CCO-COLLAPSIBLE:END */

/* US-CCO-RAIL:START — the right-hand rail for card and rail CCOs, then
   us-cco-rail (v1's edge-attached sidebar) and its extras: tab search, tab
   counts and the phone Sections dropdown. Behaviour: US-CCO-SIDEBAR in
   zUnionSuite.js. */

/* "Vertical right" with us-cco-cards or us-cco-rail: the rail sits right of
   the content on desktop, away from the iMIS navigation; the collapse toggle
   stays at the top of the rail's column, now top right, with mirrored icons. */
@media (min-width: 601px) {
  :root :is(.us-cco-cards, .us-cco-rail) :is(.cco, .tabs-wrapper).tabs-vertical.tabs-right:not(:where(:is(.us-cco-cards, .us-cco-rail) :is(.cco, .tabs-wrapper) :is(.cco, .tabs-wrapper), .us-report-no-styling, .us-report-no-styling *)) {
    grid-template-columns: minmax(0, 1fr) var(--us-cco-rail-width);
  }

  :root :is(.us-cco-cards, .us-cco-rail) :is(.cco, .tabs-wrapper).tabs-vertical.tabs-right:not(:where(:is(.us-cco-cards, .us-cco-rail) :is(.cco, .tabs-wrapper) :is(.cco, .tabs-wrapper), .us-report-no-styling, .us-report-no-styling *)) > .RadTabStripVertical {
    grid-column: 2;
    --active-shadow: inset -3px 0 0 var(--accent);
  }

  :root :is(.us-cco-cards, .us-cco-rail) :is(.cco, .tabs-wrapper).tabs-vertical.tabs-right:not(:where(:is(.us-cco-cards, .us-cco-rail) :is(.cco, .tabs-wrapper) :is(.cco, .tabs-wrapper), .us-report-no-styling, .us-report-no-styling *)) > .RadMultiPage {
