  :root :is(.us-cco-collapsible, .us-cco-rail) :is(.cco, .tabs-wrapper).tabs-vertical.tabs-right[data-us-cco-rail="expanded"] > .us-cco-rail-toggle {
    grid-column: 2;
    justify-self: end;
