  /* Collapsed: one column again; the bar and its toggle sit on the right. */
  :root :is(.us-cco-collapsible, .us-cco-rail) :is(.cco, .tabs-wrapper).tabs-vertical.tabs-right[data-us-cco-rail="collapsed"] {
    grid-template-columns: minmax(0, 1fr);
  }

  :root :is(.us-cco-collapsible, .us-cco-rail) :is(.cco, .tabs-wrapper).tabs-vertical.tabs-right[data-us-cco-rail="collapsed"] > :is(.RadTabStripVertical, .RadMultiPage) {
    grid-column: 1;
