  body.us-banner-page :where(.main > .ContentPanel > div > .row > .col-sm-12) .us-cco-rail:not(:where(.row .row .us-cco-rail)) :is(.cco, .tabs-wrapper).tabs-vertical:not([data-us-cco-rail="collapsed"]):not(:where(.us-cco-rail :is(.cco, .tabs-wrapper) :is(.cco, .tabs-wrapper), .us-report-no-styling, .us-report-no-styling *)) > .RadTabStripVertical {
    margin-inline-start: calc(var(--bs-gutter-x) * -.5);
