  body.us-banner-page :where(.main > .ContentPanel > div > .row > .col-sm-12) .us-cco-rail:not(:where(.row .row .us-cco-rail)) :is(.cco, .tabs-wrapper).tabs-vertical.tabs-right:not([data-us-cco-rail="collapsed"]):not(:where(.us-cco-rail :is(.cco, .tabs-wrapper) :is(.cco, .tabs-wrapper), .us-report-no-styling, .us-report-no-styling *)) > .RadTabStripVertical {
    margin-inline-start: 0;
    margin-inline-end: calc(var(--bs-gutter-x) * -.5);
  }

  :root .us-cco-rail :is(.cco, .tabs-wrapper).tabs-vertical:not([data-us-cco-rail="collapsed"]):not(:where(.us-cco-rail :is(.cco, .tabs-wrapper) :is(.cco, .tabs-wrapper), .us-report-no-styling, .us-report-no-styling *)) > .RadTabStripVertical > .rtsLevel > .rtsUL > .rtsLI > .rtsLink {
    transition: background-color 150ms, color 150ms;
