  :root .us-cco-rail:is(.us-cco-collapsible, .us-cco-rail) :is(.cco, .tabs-wrapper).tabs-vertical[data-us-cco-rail="expanded"] > .RadTabStripVertical {
    grid-row: 1 / span 2;
