  :root .us-cco-rail:is(.us-cco-collapsible, .us-cco-rail) :is(.cco, .tabs-wrapper).tabs-vertical[data-us-cco-rail="expanded"] > .us-cco-rail-toggle {
    margin-top: calc(8px - var(--us-cco-rail-pull, 0px));
