  :root .us-cco-rail:is(.us-cco-collapsible, .us-cco-rail) :is(.cco, .tabs-wrapper).tabs-vertical[data-us-cco-rail="collapsed"] > .RadTabStripVertical {
    margin-top: calc(4px - var(--us-cco-rail-pull, 0px));
