  padding: 7px 10px;
  border: 1px solid var(--border-strong);
  border-radius: 6px;
  background-color: var(--bg-surface);
  color: var(--text-base);
  font: 13px/1.5 var(--font-ui);
  box-shadow: none;
}

/* Hover and focus as the shared form fields (us-form): the field rule above
   replaced the native look, so the states are restored here. */
.us-credentials :is(
  input[type="text"],
  input[type="password"],
  select
):not(.riTextBox, .rdfd_):hover:not(:disabled, .aspNetDisabled, [readonly]):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
