  outline: 2px solid transparent;
  outline-offset: 2px;
  border-color: var(--field-focus-colour);
  box-shadow: var(--field-focus-glow);
}

/* Username and email are shown, not edited, here. */
.us-credentials :is(input[type="text"], input[type="password"]):is(:disabled, .aspNetDisabled):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  border-color: var(--border);
  background-color: var(--bg-subtle);
  color: var(--text-base);
