   Panel Editor forms do. */
.us-credentials label.Required:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  background-image: none !important;
}

.us-credentials label.Required:not(:where(.us-report-no-styling, .us-report-no-styling *))::before {
  content: "*";
  margin-right: 4px;
  color: var(--danger);
}

.HideRequiredAsterisks .us-credentials label.Required:not(:where(.us-report-no-styling, .us-report-no-styling *))::before,
.us-credentials .HideRequiredAsterisks label.Required:not(:where(.us-report-no-styling, .us-report-no-styling *))::before {
  display: none;
}

/* Calendar validators reserve space while hidden (visibility, not display). */
.us-credentials .ValidationError[style*="visibility:hidden"]:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: none;
}

.us-credentials .ValidationError:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  color: var(--danger);
  font-size: 12px;
}

/* Contact information: ID and full name in the credentials label column. */
.us-credentials [id$="_ContactInfoPanel_Body"]:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: grid;
  grid-template-columns: var(--us-credentials-label) minmax(0, 1fr);
  align-items: baseline;
  gap: 10px 16px;
}

.us-credentials [id$="_ContactInfoPanel_Body"] > .PanelField:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: contents;
}

/* ── 3. User credentials: fields beside the password reset card ───────── */

.us-credentials [id$="_UserInfoPanel_Body"]:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: grid;
  grid-template-columns: minmax(0, calc(var(--us-credentials-label) + var(--us-credentials-field) + 16px)) minmax(260px, 340px);
  grid-template-areas:
    "fields reset"
    "details .";
  justify-content: start;
  align-items: start;
  gap: 24px 48px;
}

.us-credentials [id$="_UserInfoPanel_Body"] > .PanelField:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  grid-area: fields;
}

.us-credentials [id$="_UserInfoPanel_Body"] > [id$="_ResetPasswordPanel"]:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  grid-area: reset;
}

/* Locked out, Last sign in, Last active and User class: their own block
   (US-CREDENTIALS JS moves them out of the Username field). Below the
   fields, set apart by a rule, its values aligned with theirs; beside them
   on a wide panel (section 8). */
.us-credentials [id$="_UserInfoPanel_Body"] > .us-credentials__details:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: grid;
  grid-area: details;
  grid-template-columns: var(--us-credentials-label) minmax(0, max-content);
  align-items: center;
  align-content: start;
  gap: 12px 16px;
  padding-top: 16px;
  border-top: 1px solid var(--bg-sunken);
}

.us-credentials .us-credentials__details > .PanelField:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: grid;
  grid-column: 1 / -1;
  grid-template-columns: subgrid;
  align-items: center;
  row-gap: 4px;
}

.us-credentials .us-credentials__details > .PanelField > :is(label, .Label):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  grid-column: 1;
}

.us-credentials .us-credentials__details > .PanelField > :is(.PanelFieldValue, .ValidationError):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  grid-column: 2;
  min-width: 0;
  margin: 0;
}

/* The block's own rule replaces the divider above Locked out. */
.us-credentials .us-credentials__details > #LockoutStatus:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  margin-top: 0;
  padding-top: 0;
  border-top: 0;
}

/* The Username field wraps every other field: one label/value grid. */
.us-credentials [id$="_UserInfoPanel_Body"] > .PanelField:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: grid;
  grid-template-columns: var(--us-credentials-label) minmax(0, var(--us-credentials-field));
  align-items: center;
  gap: 12px 16px;
}

.us-credentials [id$="_UserInfoPanel_Body"] > .PanelField > .PanelField:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: grid;
  grid-column: 1 / -1;
  grid-template-columns: subgrid;
  align-items: center;
  row-gap: 4px;
}

.us-credentials [id$="_UserInfoPanel_Body"] > .PanelField > :is(label, .Label):not(:where(.us-report-no-styling, .us-report-no-styling *)),
.us-credentials [id$="_UserInfoPanel_Body"] > .PanelField > .PanelField > :is(label, .Label):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
