}

.us-credentials [id$="_UserInfoPanel_Body"] > .PanelField > .PanelFieldValue:not(:where(.us-report-no-styling, .us-report-no-styling *)),
.us-credentials [id$="_UserInfoPanel_Body"] > .PanelField > .PanelField > :is(.PanelFieldValue, .ValidationError):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
