  align-items: center;
  gap: 8px;
}

/* Password: the native inline-block wrapper would shrink the input. */
.us-credentials [id$="_PasswordEdit1_Password"]:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  width: 100%;
}

.us-credentials .PanelFieldValue > div:has(> div > [id$="_PasswordEdit1_Password"]):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
