  border-radius: 6px;
  background: transparent var(--us-credentials-trash) center / 18px no-repeat;
  color: transparent;
  font-size: 0;
  object-fit: none;
  object-position: -9999px -9999px;
  cursor: pointer;
}

.us-credentials input[type="image"]:is([id$="_RemoveUserButton"], [id$="_gbcDeleteColumn"]):hover:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
