  margin: 0;
}

.us-credentials [id$="_UserSecurityInfoPanel_Body"] > .row > [class*="col-"]:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  width: auto;
  min-width: 0;
  padding: 0;
  float: none;
}

.us-credentials [id$="_UserSecurityInfoPanel_Body"] > .row > [class*="col-"] > div:not(.panel):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
