.us-credentials [id$="_UserSecurityInfoPanel_Body"] .panel-border > .panel-body-container:not(:where(.us-report-no-styling, .us-report-no-styling *)),
.us-credentials [id$="_UserSecurityInfoPanel_Body"] .panel-border .panel-body:not(:where(.us-report-no-styling, .us-report-no-styling *)),
.us-credentials [id$="_UserSecurityInfoPanel_Body"] .panel-border .panel-body > [data-gridid]:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
