  flex: 1 1 auto;
  flex-direction: column;
  min-height: 0;
}

.us-credentials [id$="_UserSecurityInfoPanel_Body"] .panel-border .panel-body:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  padding: 0;
}

.us-credentials [id$="_UserSecurityInfoPanel_Body"] .panel-border [id$="_GridPanel1"]:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  flex: 1 1 auto;
}

