}

.us-credentials [id$="_UserSecurityInfoPanel_Body"] .GridTitlePanel .Title:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  margin: 0;
  padding: 0;
  color: var(--text-strong);
  font: 600 13px/1.4 var(--font-ui);
}

.us-credentials [id$="_UserSecurityInfoPanel_Body"] .GridTitlePanel > [id$="_TopLeftPanel"]:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
