}

.us-credentials [id$="_UserSecurityInfoPanel_Body"] .GridTitlePanel:not(:where(.us-report-no-styling, .us-report-no-styling *))::before,
.us-credentials [id$="_UserSecurityInfoPanel_Body"] .GridTitlePanel:not(:where(.us-report-no-styling, .us-report-no-styling *))::after {
