  gap: 4px;
  box-sizing: border-box;
  height: 28px;
  padding: 0 10px;
  border: 1px solid var(--border-strong);
  border-radius: 6px;
  background: var(--bg-surface);
  color: var(--text-link);
  font: 600 12px/1 var(--font-ui);
  text-decoration: none;
}

.us-credentials [id$="_UserSecurityInfoPanel_Body"] [id$="_TopRightPanel"] > a:not(:where(.us-report-no-styling, .us-report-no-styling *))::before {
  content: "+";
  font-size: 15px;
