:root .us-actions:not(:where(.us-report-no-styling, .us-report-no-styling *, [data-us-actions-ignore], [data-us-actions-ignore] *)) :is(.us-actions__item, .us-actions__subtoggle):hover,
:root .us-actions:not(:where(.us-report-no-styling, .us-report-no-styling *, [data-us-actions-ignore], [data-us-actions-ignore] *)) .us-actions__subtoggle[aria-expanded=true] {
