:root .us-actions:not(:where(.us-report-no-styling, .us-report-no-styling *, [data-us-actions-ignore], [data-us-actions-ignore] *)) :is(.us-actions__item, .us-actions__subtoggle, .us-actions__toggle):is(:disabled, [aria-disabled=true], .disabled):not(:where(.us-action-conflict)) {
