/* The list is as wide as its longest item, not Quick Actions' 288px. */
:root .us-actions.us-heading-menu:not(:where(.us-report-no-styling, .us-report-no-styling *, [data-us-actions-ignore], [data-us-actions-ignore] *))[data-us-actions-ready] .us-actions__list {
