:root .us-actions.us-heading-menu:not(:where(.us-report-no-styling, .us-report-no-styling *, [data-us-actions-ignore], [data-us-actions-ignore] *)) > .us-actions__list::before {
  content: '';
  display: none;
  position: absolute;
  z-index: 2;
  top: -2px;
  left: 15.5px;
  width: 2px;
  height: 12px;
  border-radius: 2px;
  background: linear-gradient(to bottom, transparent, var(--brand-600) 65%, var(--accent));
