/* US-TASK-ROWS:START — task result content and a whole-query footer. */
:where(.panel-body):has(> .QueryTemplateSet) {
  --us-query-body-inset: var(--iqa-inset,18px);
  --us-query-body-block-inset: var(--space-3,12px);
