.us-task:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  width: 100%;
  box-sizing: border-box;
  padding: 0 20px;
  color: var(--text-base);
  font: 14px/1.5 var(--font-ui);
  transition: background 160ms;
}

.us-task:not(:where(.us-report-no-styling, .us-report-no-styling *)):is(:hover, :focus-within) {
  background: var(--bg-sunken);
}

.us-task__open:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: flex;
  align-items: center;
  gap: 16px;
  flex: 1;
  min-width: 0;
  padding: 12px 0;
  border: 0;
  background: transparent;
  color: var(--text-base);
  font: inherit;
  text-align: start;
  text-decoration: none;
}

:is(a, button).us-task__open:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  cursor: pointer;
}

.us-task__copy:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
