  min-width: 0;
  overflow-wrap: anywhere;
}

.us-task__copy > strong:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: block;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-strong);
  line-height: 1.4;
}

.us-task__copy > span:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: block;
  font-size: 12px;
  color: var(--text-muted);
  margin-top: 4px;
}

.us-task__date:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  flex: none;
  text-align: right;
  font-size: 12px;
  color: var(--text-muted);
}

.us-task__check:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  box-sizing: border-box;
  width: 36px;
  height: 36px;
  padding: 0;
  margin: 0;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--white);
  cursor: pointer;
}

.us-task__check:not(:where(.us-report-no-styling, .us-report-no-styling *))::before {
  content: "";
  position: absolute;
  inset: 6px;
  border: 2px solid var(--border);
  border-radius: 6px;
  background: var(--bg-surface);
  transition: background 160ms,border-color 160ms;
}

.us-task__check:hover:not(:where(.us-report-no-styling, .us-report-no-styling *))::before {
