}

.us-task__check > svg:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  position: relative;
  width: 18px;
  height: 18px;
  opacity: 0;
  pointer-events: none;
}

.us-task__check[aria-checked="true"]:not(:where(.us-report-no-styling, .us-report-no-styling *))::before {
  border-color: var(--success);
  background: var(--success);
}

.us-task__check[aria-checked="true"] > svg:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  opacity: 1;
}

.us-task:is([data-us-task-completed="true" i], [data-us-task-completed="1"], .us-task--complete) .us-task__copy > strong:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  text-decoration: line-through;
  color: var(--text-muted);
  font-weight: 400;
}

.us-task:is([data-us-task-completed="true" i], [data-us-task-completed="1"], .us-task--complete) .us-task__date:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  color: var(--success);
  background: var(--success-bg);
  padding: 3px 8px;
  border-radius: var(--radius-sm);
}

.us-task :is(button, a):focus-visible:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

/* Detail row (compact, owner 2 October 2026): two lines, as the original
   agreement tasks. The title, then the date and member together; an optional
   one-line note between them; an optional us-task__aside on the right for
   badges and a view button. Opt in with us-task--detail on the row; lists
   using the original two-line task row are unaffected, because every rule
   below carries the modifier. Gaps are margins rather than column-gap, so a
   blank date or an absent aside leaves no stranded gap. Requires
   Tasks-Detail-Query-Template.html, whose markup supplies the title link,
   note, member and date elements these rules place. */
.QueryTemplateSet:has(.us-task--detail):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  container-type: inline-size;
  container-name: us-tasks;
}

.us-task--detail:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: grid;
  grid-template-columns: auto max-content minmax(0, 1fr) auto;
  grid-template-areas:
    "check title title aside"
    "check note  note  aside"
    "check due   meta  aside";
  align-items: center;
  align-content: center;
  /* Both gaps stated: the phone rule sets gap: 8px on .us-task. */
  column-gap: 0;
  row-gap: 0;
  min-height: 52px;
  padding: 8px 20px;
}

.us-task--detail > .us-task__check:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  grid-area: check;
  align-self: center;
  margin: 0 12px 0 0;
}

/* A row with a note runs to three lines; the tick then stays with the title,
   so the tick and the thing it completes read as one unit. */
.us-task--detail:has(.us-task__note:not(:empty)) > .us-task__check:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  align-self: start;
  margin-top: -5px;
}

/* The wrappers the original row needs for its flex line become transparent, so
   their children can take grid areas directly. */
.us-task--detail > .us-task__open:not(:where(.us-report-no-styling, .us-report-no-styling *)),
.us-task--detail .us-task__copy:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: contents;
}

/* The title wins every tie for width. Medium weight, so a long list scans
   without every row shouting. It is plain text now and the pencil opens the
   task (owner, 7 October 2026); the earlier template's title is a link.
   Matched as a.us-task__title on purpose: dark mode colours links inside
   .panel-body at (0,3,1), so a class-only rule loses and titles turn link blue. */
.us-task--detail :is(a, span).us-task__title:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  grid-area: title;
  justify-content: flex-start;
  max-width: 62ch;
  font-size: var(--fs-sm);
  font-weight: var(--fw-medium);
  line-height: 1.4;
  color: var(--text-strong);
  text-decoration: none;
  overflow-wrap: anywhere;
}

.us-task--detail a.us-task__title:hover:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  text-decoration: underline;
}

/* One line, clamped rather than hidden: clamped text still matches the header
   search, where a hidden excerpt copy would silently stop matching. The rest of
   the note belongs to the task record, not the list. */
.us-task--detail .us-task__note:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  grid-area: note;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 1;
  max-width: 78ch;
  overflow: hidden;
  font-size: 13px;
  line-height: 1.45;
  color: var(--text-muted);
}

/* The second line, date then member, is paler than the title. */
.us-task--detail .us-task__meta:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  grid-area: meta;
  display: flex;
  flex-wrap: wrap;
  align-self: baseline;
  align-items: baseline;
  gap: 4px 12px;
  margin-top: 2px;
  min-width: 0;
  font-size: 12px;
  color: var(--text-faint);
}

/* The person icon labels the member without spending a word. */
.us-task--detail .us-task__member:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
  min-width: 0;
  font-weight: var(--fw-normal);
  color: inherit;
}

.us-task--detail .us-task__member > .ti:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  flex: none;
  align-self: center;
  font-size: 12px;
  line-height: 1;
  color: var(--text-muted);
  transition: color 120ms;
}

/* Hovering the name lights the icon too, so the pair reads as one control. */
.us-task--detail .us-task__member:has(> a.us-task__member-name[href]:hover) > .ti:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  color: var(--accent);
}

/* The member link keeps the meta line's appearance rather than taking link colour:
   two differently coloured links in one row compete. Underline on hover marks it. */
.us-task--detail a.us-task__member-name:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  min-width: 0;
  color: inherit;
  text-decoration: none;
  overflow-wrap: anywhere;
}

.us-task--detail a.us-task__member-name[href]:hover:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  text-decoration: underline;
}

.us-task--detail a.us-task__member-name[aria-disabled="true"]:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  cursor: default;
}

/* The date leads the second line, before the member, and takes the width
   its text needs. */
.us-task--detail .us-task__date:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  grid-area: due;
  align-self: baseline;
  max-width: none;
  margin: 2px 12px 0 0;
  padding-left: 0;
  text-align: start;
  color: var(--text-faint);
}

/* A blank query value must not leave an empty line or a stranded icon: row rhythm
   follows the layout, not the data. */
.us-task--detail :is(.us-task__note, .us-task__meta, .us-task__date):empty:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: none;
}

.us-task--detail .us-task__member:has(> a.us-task__member-name:empty):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: none;
}

/* Overdue is the only coloured state, and the query supplies the word "Overdue"
   with it, so the state never rests on colour alone. Due today keeps the weight
   without a second colour. A badge would cost 80-110px of contested width. */
.us-task--detail[data-us-task-due-state="overdue" i] .us-task__date:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  font-weight: 600;
  color: var(--danger);
}

.us-task--detail[data-us-task-due-state="today" i] .us-task__date:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  font-weight: 600;
}

/* data-us-task-due-state comes from the query and is not updated when a row is
   ticked, so the completed row resets the weight as well as the pill. Both
   selectors match the due-state rules' specificity and follow them, so they win. */
.us-task--detail.us-task--complete .us-task__date:not(:where(.us-report-no-styling, .us-report-no-styling *)),
.us-task--detail[data-us-task-completed="true" i] .us-task__date:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  padding: 0;
  background: none;
  font-weight: 400;
  color: var(--success);
}

.us-task--detail.us-task--complete :is(a, span).us-task__title:not(:where(.us-report-no-styling, .us-report-no-styling *)),
.us-task--detail[data-us-task-completed="true" i] :is(a, span).us-task__title:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  color: var(--text-muted);
  text-decoration: line-through;
}

/* Optional aside on the right: badges and a view button. */
.us-task__aside:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  grid-area: aside;
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin-inline-start: 12px;
}

.us-task__aside:empty:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: none;
}

.us-task__aside .us-badge:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: var(--fs-2xs);
  white-space: nowrap;
}

/* The view button is secondary to the title link, so it stays quiet until
   hovered. */
.us-task__aside .us-icon-button:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  color: var(--text-faint);
}

.us-task__aside .us-icon-button:is(:hover, :focus-visible):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  color: var(--icon-hover-colour);
}

/* A completed row keeps its badges but drops their colour, like its title. */
.us-task--detail:is(.us-task--complete, [data-us-task-completed="true" i]) .us-task__aside .us-badge:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  opacity: 0.55;
}

/* Shown in place when a completion cannot be saved, so a rejected write is
   visible on the task rather than only in the console. */
.us-task__save-error:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  grid-column: 2 / -1;
  margin-top: 4px;
  font-size: 12px;
  font-weight: 600;
  color: var(--danger);
}

/* A narrow list cannot fit a long date beside the member, so the member drops
   below the date. */
@container us-tasks (max-width: 479.98px) {
  .us-task--detail:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
    grid-template-columns: auto minmax(0, 1fr) auto;
    grid-template-areas:
      "check title aside"
      "check note  aside"
      "check due   aside"
      "check meta  aside";
  }
}

