.ContentItemContainer :is(.panel-body-container > .panel-body):has(> .QueryTemplateSet > section > .QueryTemplateItem > .us-task, > .QueryTemplateSet > .QueryTemplateItem > .us-task):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
