/* Decorative completion overlay. Palette inherits from the task control. */
:root {
  --task-confetti-1: var(--accent);
  --task-confetti-2: var(--brand-500);
  --task-confetti-3: var(--success);
  --task-bats-1: #8f79c6;
  --task-bats-2: #6f569f;
  --task-bats-3: #e8aa58;
}

.us-task-particle {
  position: fixed;
  z-index: var(--z-tooltip,1000);
  pointer-events: none;
  width: 15px;
  height: 15px;
  will-change: transform,opacity;
}

.us-task-particle svg {
  display: block;
  width: 100%;
  height: 100%;
  fill: currentColor;
}

.us-task-particle[data-us-task-effect="night"] {
  width: 19px;
  height: 19px;
}

.us-task-particle[data-us-task-effect="bats"] {
  width: 24px;
  height: 24px;
}

@media (prefers-reduced-motion:reduce) {
  .us-task-particle {
    display: none;
  }
}

@media print {
  .us-task-particle {
    display: none;
  }
}

/* Compact and full task rows (owner, 19 October 2026): one task row in two
   versions, on the detail row's grid (us-task--detail), for the homepage, the
   agreement page and the case page alike.
   - us-task--compact (the default): title, then date, member and tags. A task
     with a note gets a details button beside the pencil, which opens the
     note under the row in place.
   - us-task--full (optional): the note shows too, up to two lines, with a
     More link when it is longer.
   Both: the title is plain text and a pencil at the end of the row edits;
   the badge and buttons share the title's first line, which never moves;
   an opened note runs the full width below; tags end the meta line, the
   first and "+2" (a button) for the rest. Templates:
   Tasks-Compact-Query-Template.html and Tasks-Full-Query-Template.html.
   Behaviour (More, details, tags, the slide) is US-TASK-ROWS in
   zUnionSuite.js. Every rule names one of the two modifiers or an element
   only they carry, so the detail row and the older row are unchanged. */

/* One layout for both versions (owner, 19 October 2026): the title, badge
   and buttons on the first line, which never moves; the note across the
   full width below (under the buttons too), with a line for More; then the
   date and member. The compact row simply has no note line until opened. */
.us-task--detail:is(.us-task--full, .us-task--compact):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  grid-template-areas:
    "check title title aside"
    "check note  note  note"
    "check more  more  more"
    "check due   meta  meta";
}

.us-task--full .us-task__note:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  -webkit-line-clamp: 2;
}

/* More / Less: a quiet text link at the start of its own line. The theme adds
   it only when the note runs past two lines. */
.us-task__more:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  grid-area: more;
  justify-self: start;
  margin: 1px 0 0;
  padding: 0;
  border: 0;
  background: none;
  color: var(--text-link);
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  line-height: 1.5;
  cursor: pointer;
}

.us-task__more:hover:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  text-decoration: underline;
}

.us-task__more:focus-visible:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  outline: 2px solid transparent;
  border-radius: var(--radius-sm);
  box-shadow: var(--focus-ring);
}

/* An open note shows in full. */
.us-task--detail[data-us-task-expanded] .us-task__note:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: block;
  -webkit-line-clamp: unset;
  overflow: visible;
}

/* ── Compact ───────────────────────────────────────────────── */

/* No note line until the details button opens it. The note stays in the
   markup, so the list search still matches it. */
.us-task--compact:not([data-us-task-expanded]) .us-task__note:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: none;
}

/* An opened note starts clear of the pressed details button, whose fill
   reaches about 11px below the title line (owner, 19 October 2026), and sits
   a little apart from the meta line. */
.us-task--compact[data-us-task-expanded] .us-task__note:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  margin: 10px 0 4px;
}

/* The details button: quiet like the pencil, and only on a task that has a
   note. Pressed (open), it takes the link colour. */
.us-task__details:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: inline-grid;
  place-items: center;
  width: 32px;
  height: 32px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: var(--radius);
  background: none;
  color: var(--text-faint);
  cursor: pointer;
  transition:
    background-color 150ms cubic-bezier(.2, 0, 0, 1),
    color 150ms cubic-bezier(.2, 0, 0, 1);
}

.us-task__details .ti:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  font-size: 18px;
}

.us-task__details:hover:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  background: var(--bg-sunken);
  color: var(--icon-hover-colour, var(--text-strong));
}

/* Open: the theme's one "on" state for toggles (the heading filter and
   Show completed buttons), so it stands out on a hovered row too. */
.us-task__details[aria-expanded="true"]:not(:where(.us-report-no-styling, .us-report-no-styling *)),
.us-task__details[aria-expanded="true"]:hover:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  border-color: color-mix(in srgb, var(--iqa-link, var(--text-link)) 28%, transparent);
  background: var(--iqa-selected, var(--brand-100));
  box-shadow: inset 0 1px 3px rgb(0 0 0 / .14);
  color: var(--iqa-link, var(--text-link));
}

@media (forced-colors: active) {
  .us-task__details[aria-expanded="true"]:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
    border: 2px solid Highlight;
  }
}

.us-task__details:focus-visible:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  outline: 2px solid transparent;
  box-shadow: var(--focus-ring);
}

.us-task__details[aria-expanded="true"]:focus-visible:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  box-shadow: inset 0 1px 3px rgb(0 0 0 / .14), var(--focus-ring);
}

.us-task--compact:has(.us-task__note:empty) .us-task__details:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: none;
}

/* ── Untitled ──────────────────────────────────────────────── */

/* A task with no title (legacy notes, owner 20 October 2026): the note
   takes the title's place and look, up to two lines, on compact rows too.
   A compact row keeps its details button only while the note is cut short
   (data-us-task-clipped, from US-TASK-ROWS), and opening it shows the note
   in full where it is; a full row keeps its More link. */
.us-task--detail:is(.us-task--full, .us-task--compact):has(.us-task__title:empty) .us-task__title:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: none;
}

.us-task--detail:is(.us-task--full, .us-task--compact):has(.us-task__title:empty) .us-task__note:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  grid-area: title;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  max-width: 62ch;
  margin: 0;
  padding-block: 2px;
  font-size: var(--fs-sm);
  font-weight: var(--fw-medium);
  line-height: 1.4;
  color: var(--text-strong);
}

.us-task--detail:is(.us-task--full, .us-task--compact)[data-us-task-expanded]:has(.us-task__title:empty) .us-task__note:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: block;
  -webkit-line-clamp: unset;
  overflow: visible;
}

.us-task--detail:is(.us-task--full, .us-task--compact):is(.us-task--complete, [data-us-task-completed="true" i]):has(.us-task__title:empty) .us-task__note:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  color: var(--text-muted);
  text-decoration: line-through;
}

.us-task--compact:has(.us-task__title:empty):not([data-us-task-clipped], [data-us-task-expanded]) .us-task__details:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: none;
}

/* ── Both ──────────────────────────────────────────────────── */

/* The badge and buttons sit on the title's first line (owner, 19 October
   2026): with a long title they stay level with its start, so every pencil
   is in the same place down the list. The title line is padded to the
   badge's 22px, so the badge sits inside it and never meets the date line
   (or "+2") below; only the 36px buttons' empty edges overhang the line,
   instead of stretching it, so a short row stays tight. */
.us-task--detail:is(.us-task--full, .us-task--compact) :is(a, span).us-task__title:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  padding-block: 2px;
}

.us-task--detail:is(.us-task--full, .us-task--compact) > .us-task__aside:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  align-self: start;
  margin-block: -3px -11px;
}

/* The note runs the full width, so it is not held to the title's measure. */
.us-task--detail:is(.us-task--full, .us-task--compact) .us-task__note:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  max-width: none;
}

/* The tick sits on the title's first line too, on every row (the detail
   row's -5px, plus the title line's 2px padding). .us-task matches the
   detail row's rule's weight, and this rule comes after it, so it wins. */
.us-task.us-task--detail:is(.us-task--full, .us-task--compact) > .us-task__check:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  align-self: start;
  margin-top: -3px;
}

/* Tags end the meta line, as quiet as the member: a tag icon, the first tag
   and "+2" for the rest; all of them while the note is open. A task without
   tags shows nothing. */
.us-task--detail .us-task__tags:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
  min-width: 0;
  color: inherit;
}

.us-task--detail .us-task__tags > .ti:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  flex: none;
  align-self: center;
  font-size: 12px;
  line-height: 1;
  color: var(--text-muted);
}

.us-task--detail .us-task__tags-text:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  min-width: 0;
  overflow-wrap: anywhere;
}

/* "+2" is a small button: it shows every tag in place. */
.us-task--detail .us-task__tags-more:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  margin-inline-start: 4px;
  padding: 0 5px;
  border: 0;
  border-radius: var(--radius-pill);
  background: var(--bg-sunken);
  color: var(--text-strong);
  font: inherit;
  font-weight: 600;
  line-height: 1.5;
  cursor: pointer;
  transition: background-color 150ms cubic-bezier(.2, 0, 0, 1);
}

.us-task--detail .us-task__tags-more:hover:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  background: var(--border);
}

.us-task--detail .us-task__tags-more:focus-visible:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  outline: 2px solid transparent;
  box-shadow: var(--focus-ring);
}

.us-task--detail .us-task__tags-text:focus:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  outline: none;
}

.us-task--detail .us-task__tags:has(> .us-task__tags-text:empty):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: none;
}

/* A blank priority leaves no empty badge beside the pencil. */
.us-task--detail .us-task__aside .us-badge:empty:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
  display: none;
}

/* ── Narrow lists ──────────────────────────────────────────── */
@container us-tasks (max-width: 479.98px) {
  .us-task--detail:is(.us-task--full, .us-task--compact):not(:where(.us-report-no-styling, .us-report-no-styling *)) {
    grid-template-areas:
      "check title aside"
      "check note  note"
      "check more  more"
      "check due   due"
      "check meta  meta";
  }
}

@media (prefers-reduced-motion: reduce) {
  .us-task__details:not(:where(.us-report-no-styling, .us-report-no-styling *)) {
    transition: none;
  }
}

/* US-TASK-ROWS:END */

/* US-MILESTONES:START — us-milestones. Progress above the list (built by
   US-MILESTONES JS from the rows), then one row per milestone (stage).
   With us-milestones--bar (in the us-agreement-milestones preset) progress
   is a segmented bar with the next milestone named under it; without it,
   the numbered rail. A row is a status icon (us-milestone__status-button)
   that opens the status menu, the title, the status in words and the
   pencil; rows from the earlier template have a dot, a title link, a date
   and a status select. data-us-milestone-status holds the TaskStatus (Not
   Complete, In Progress, Complete; matched ignoring case). Completed rows
   carry data-us-task-completed, so us-task-completed-filter hides them
   until "Show completed" is pressed. Reordering (us-milestones--reorder)
   follows, as US-MILESTONE-ORDER. */

/* ── The rail (without us-milestones--bar) ─────────────────────── */

.us-milestones__rail {
  --milestone-node: 28px;
  position: relative;
  display: flex;
  justify-content: space-between;
  gap: 4px;
  margin: 0 0 var(--space-3);
  padding: 4px 0 var(--space-3);
  overflow-x: auto;
  border-bottom: 1px solid var(--border);
  list-style: none;
}

.us-milestones__rail::before,
.us-milestones__rail::after {
  content: "";
  position: absolute;
  top: calc(4px + var(--milestone-node) / 2 - 1px);
  inset-inline-start: calc(var(--milestone-node) / 2);
  height: 2px;
  border-radius: var(--radius-pill);
}

.us-milestones__rail::before {
  inset-inline-end: calc(var(--milestone-node) / 2);
  background: var(--border);
}

/* Progress scales the full-length line, so it animates without layout. */
.us-milestones__rail::after {
  width: calc(100% - var(--milestone-node));
  background: var(--success-fill);
  transform: scaleX(var(--milestones-progress, 0));
  transform-origin: left center;
  transition: transform 0.3s ease;
}

/* Nodes share the panel width; a long rail (more than about eight
   milestones in a half-width panel) scrolls sideways instead. */
.us-milestones__node {
  position: relative;
  z-index: 1;
  display: flex;
  flex: 1 1 0;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  min-width: 44px;
  max-width: 120px;
  text-align: center;
}

.us-milestones__circle {
  display: grid;
  place-items: center;
  width: var(--milestone-node);
  height: var(--milestone-node);
  border: 2px solid var(--border-strong);
  border-radius: 50%;
  background: var(--bg-surface);
  color: var(--text-muted);
  font-size: var(--fs-xs);
  font-weight: var(--fw-semi);
}

.us-milestones__node[data-us-milestone-status="In Progress" i] .us-milestones__circle {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--text-on-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 20%, transparent);
}

.us-milestones__node[data-us-milestone-status="Complete" i] .us-milestones__circle {
  border-color: var(--success-fill);
  background: var(--success-fill);
  color: var(--text-on-accent);
}

.us-milestones__circle svg {
  width: 14px;
  height: 14px;
}

.us-milestones__label {
  display: -webkit-box;
  overflow: hidden;
  color: var(--text-base);
  font-size: var(--fs-xs);
  font-weight: var(--fw-medium);
  line-height: var(--lh-tight);
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

/* ── The bar (us-milestones--bar) ──────────────────────────────── */

.us-milestones__bar {
  margin: 0 0 var(--space-3);
  padding: 2px 0 var(--space-3);
  border-bottom: 1px solid var(--border);
}

.us-milestones__segments {
  display: flex;
  gap: 3px;
}

/* An 8px segment per milestone, with an invisible 4px margin above and
   below so the pointer finds it easily. */
.us-milestones__segment {
  flex: 1 1 0;
  box-sizing: content-box;
  height: 8px;
  border-block: 4px solid transparent;
  background: var(--border-strong);
  background-clip: content-box;
  transition: background-color .2s, transform .15s;
}

.us-milestones__segment:first-child {
  border-start-start-radius: var(--radius-pill);
  border-end-start-radius: var(--radius-pill);
}

.us-milestones__segment:last-child {
  border-start-end-radius: var(--radius-pill);
  border-end-end-radius: var(--radius-pill);
}

.us-milestones__segment[data-us-milestone-status="In Progress" i] {
  background-color: var(--accent);
}

.us-milestones__segment[data-us-milestone-status="Complete" i] {
  background-color: var(--success-fill);
}

.us-milestones__segment[data-us-milestone-linked] {
  transform: scaleY(1.4);
}

.us-milestones__next {
  overflow: hidden;
  margin: 2px 0 0;
  color: var(--text-muted);
  font-size: var(--fs-xs);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.us-milestones__next strong {
  color: var(--text-strong);
  font-weight: var(--fw-semi);
}

/* ── The rows ──────────────────────────────────────────────────── */

.us-milestone {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  /* Palette for the shared completion effect (UnionSuiteTaskRows.celebrate). */
  --task-confetti-1: var(--accent);
  --task-confetti-2: var(--brand-500);
  --task-confetti-3: var(--success);
}

/* A segment and its row light each other. */
.us-milestones--bar .us-milestone {
  border-radius: var(--radius-sm);
  transition: background-color .15s, box-shadow .15s;
}

.us-milestones--bar .us-milestone[data-us-milestone-linked] {
  background: var(--bg-sunken);
  box-shadow: 0 0 0 4px var(--bg-sunken);
}

/* Status tone and icon: an empty circle, a half-filled circle or a tick,
   in the bar's colours. One definition per status, shared by the row's
   icon and words and the status menu. The menu takes the term status
   menu's look (us-term-status-menu), so its items hand the tone and icon
   to that menu's variables. */
.us-milestone,
.us-milestone-status-menu .us-term-status-menu__item {
  --us-milestone-tone: var(--text-muted);
  --us-milestone-icon: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2'><circle cx='12' cy='12' r='9'/></svg>");
}

.us-milestone[data-us-milestone-status="In Progress" i],
.us-milestone-status-menu .us-term-status-menu__item[data-us-milestone-status="In Progress" i] {
  --us-milestone-tone: var(--accent);
  --us-milestone-icon: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2'><circle cx='12' cy='12' r='9'/><path d='M12 3a9 9 0 0 1 0 18z' fill='black'/></svg>");
}

.us-milestone[data-us-milestone-status="Complete" i],
.us-milestone-status-menu .us-term-status-menu__item[data-us-milestone-status="Complete" i] {
  --us-milestone-tone: var(--success);
  --us-milestone-icon: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><circle cx='12' cy='12' r='9'/><path d='m8.5 12 2.5 2.5 4.5-5'/></svg>");
}

/* Two classes on the menu outrank the term status defaults. */
.us-milestone-status-menu.us-term-status-menu .us-term-status-menu__item {
  --us-term-tone: var(--us-milestone-tone);
  --us-term-icon: var(--us-milestone-icon);
}

/* The status icon: a button opening the status menu, sized as a term's. */
.us-milestones .us-milestone__status-button {
  position: relative;
  display: grid;
  flex: none;
  place-items: center;
  width: 32px;
  height: 32px;
  margin-inline-start: -4px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  cursor: pointer;
  transition: background-color .15s, transform .15s;
}

.us-milestones .us-milestone__status-button::before {
  content: "";
  width: 24px;
  height: 24px;
  background: var(--us-milestone-tone);
  -webkit-mask: var(--us-milestone-icon) center / contain no-repeat;
  mask: var(--us-milestone-icon) center / contain no-repeat;
  transition: background-color .2s;
}

/* In Progress keeps the rail's glow: a soft ring around the icon. */
.us-milestones .us-milestone__status-button::after {
  content: "";
  position: absolute;
  inset: 6px;
  border-radius: 50%;
  box-shadow: 0 0 0 3px transparent;
  pointer-events: none;
  transition: box-shadow .2s;
}

.us-milestone[data-us-milestone-status="In Progress" i] .us-milestone__status-button::after {
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 20%, transparent);
}

.us-milestones .us-milestone__status-button:is(:hover, [aria-expanded="true"]) {
  background: color-mix(in srgb, var(--us-milestone-tone) 14%, transparent);
}

.us-milestones .us-milestone__status-button:active {
  transform: scale(.92);
}

.us-milestones .us-milestone__status-button:focus-visible {
  outline: 0;
  box-shadow: var(--focus-ring);
}

.us-milestone[aria-busy="true"] .us-milestone__status-button {
  cursor: progress;
}

/* The earlier template's dot (it only shows the status). */
.us-milestone__dot {
  flex: none;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border-strong);
}

.us-milestone[data-us-milestone-status="In Progress" i] .us-milestone__dot {
  background: var(--accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 20%, transparent);
}

.us-milestone[data-us-milestone-status="Complete" i] .us-milestone__dot {
  background: var(--success-fill);
}

.us-milestone__copy {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
}

/* The title. In the earlier template it is the open action, drawn by the
   action runtime in link mode (us-command); now it is plain text and the
   pencil opens the milestone. */
.us-milestone .us-milestone__title {
  justify-content: flex-start;
  overflow-wrap: anywhere;
  color: var(--text-strong);
  font-size: var(--fs-sm);
  font-weight: var(--fw-medium);
  text-align: start;
  text-decoration: none;
}

.us-milestone a.us-milestone__title:hover {
  text-decoration: underline;
}

.us-milestone[data-us-milestone-status="Complete" i] .us-milestone__title {
  color: var(--text-muted);
  text-decoration: line-through;
}

/* The status in words as a term's is (US-TERMS): plain text in the status
   tone, then a dot before the date when there is one. */
.us-milestone__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 2px var(--space-1);
  margin-top: 2px;
}

.us-milestone__state {
  color: var(--us-milestone-tone);
  font-size: var(--fs-xs);
  font-weight: var(--fw-semi);
  line-height: 18px;
  white-space: nowrap;
  transition: color .2s;
}

.us-milestone__state:empty {
  display: none;
}

.us-milestone__state:not(:empty) + .us-milestone__date:not(:empty)::before {
  content: "·";
  margin-inline-end: var(--space-1);
  color: var(--text-faint);
  font-weight: var(--fw-normal);
}

.us-milestone__date {
  color: var(--text-faint);
  font-size: var(--fs-xs);
}

.us-milestone__date:empty {
  display: none;
}

/* The pencil stays at the end of the row. */
.us-milestone > .us-action-agreements-edit-milestone {
  flex: none;
}

/* The earlier template's status select. */
.us-milestones .us-milestone__status {
  flex: none;
  width: auto;
  height: 28px;
  padding-block: 0;
  font-size: var(--fs-xs);
  font-weight: var(--fw-semi);
}

.us-milestone[data-us-milestone-status="In Progress" i] .us-milestone__status {
  border-color: var(--accent);
  color: var(--accent);
}

.us-milestone[data-us-milestone-status="Complete" i] .us-milestone__status {
  border-color: var(--success-fill);
  color: var(--success);
}

.us-milestone[aria-busy="true"] .us-milestone__status {
  opacity: 0.6;
}

.us-milestone__error {
  flex-basis: 100%;
  color: var(--danger);
  font-size: var(--fs-xs);
}

.us-milestone:has(.us-milestone__error) {
  flex-wrap: wrap;
}

@media (prefers-reduced-motion: reduce) {
  .us-milestones__rail::after,
  .us-milestones__segment,
  .us-milestones--bar .us-milestone,
  .us-milestones .us-milestone__status-button,
  .us-milestones .us-milestone__status-button::before,
  .us-milestones .us-milestone__status-button::after,
  .us-milestone__state {
    transition: none;
  }
}

/* US-MILESTONES:END */

/* US-MILESTONE-ORDER:START — reordering milestones on a us-milestones--reorder
   list (US-MILESTONE-ORDER JS). While data-us-milestones-reordering is on
   the iPart wrapper, a bar above the list holds the hint, the
   announcements and Cancel / Save order; each row sits on a tile with a
   drag handle where its pencil was, and its status control steps back. */

/* The heading toggle is a shared heading icon button, which sizes its
   text to nothing; its icon is sized as the completed toggle's is. */
.us-milestones__reorder-toggle > .ti {
  font-size: 20px;
  line-height: 1;
  pointer-events: none;
}

/* While reordering, "Show completed" and Add milestone wait (inert), and
   look it. */
.us-milestones--reorder[data-us-milestones-reordering] > .panel > .panel-heading [inert] {
  opacity: .45;
  transition: opacity .15s;
}

/* The bar above the list. */
.us-milestones--reorder .us-milestones__reorder {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-1) var(--space-3);
  margin: 0 0 var(--space-3);
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--bg-sunken);
}

.us-milestones--reorder .us-milestones__reorder-hint {
  flex: 1 1 220px;
  margin: 0;
  color: var(--text-muted);
  font-size: var(--fs-xs);
}

/* Announcements: read to screen readers, and shown for an error. */
.us-milestones--reorder .us-milestones__reorder-status {
  position: absolute;
  overflow: hidden;
  width: 1px;
  height: 1px;
  margin: -1px;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.us-milestones--reorder .us-milestones__reorder[data-us-error] .us-milestones__reorder-status {
  position: static;
  flex-basis: 100%;
  order: 3;
  width: auto;
  height: auto;
  margin: 0;
  clip: auto;
  color: var(--danger);
  font-size: var(--fs-xs);
  white-space: normal;
}

.us-milestones--reorder .us-milestones__reorder-actions {
  display: flex;
  gap: var(--space-2);
  margin-inline-start: auto;
}

/* Rows while reordering: each sits on a tile reaching 4px past it; rows
   are 12px apart, so a 4px gap keeps the tiles apart. The pencil gives
   way to the handle, the status control shows the status without taking
   clicks, and completed stages lose their strike-through: here they are
   just stages in a sequence. */
.us-milestones--reorder {
  --us-reorder-tile: 4px;
}

.us-milestones--reorder[data-us-milestones-reordering] .us-milestone {
  border-radius: var(--radius-sm);
  background: var(--bg-sunken);
  box-shadow: 0 0 0 var(--us-reorder-tile) var(--bg-sunken);
}

.us-milestones--reorder[data-us-milestones-reordering] .us-milestone > .us-action-agreements-edit-milestone {
  display: none;
}

.us-milestones--reorder[data-us-milestones-reordering] .us-milestone :is(.us-milestone__status-button, .us-milestone__status) {
  opacity: .7;
}

.us-milestones--reorder[data-us-milestones-reordering] .us-milestone[data-us-milestone-status="Complete" i] .us-milestone__title {
  text-decoration: none;
}

.us-milestones--reorder .us-milestone__handle {
  display: grid;
  flex: none;
  place-items: center;
  width: 32px;
  height: 32px;
  margin-inline-start: auto;
  padding: 0;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-muted);
  font-size: 20px;
  cursor: grab;
  touch-action: none;
  animation: us-milestone-handle-in .18s cubic-bezier(.2, 0, 0, 1);
  transition: background-color .15s, color .15s;
}

.us-milestones--reorder .us-milestone__handle:hover {
  background: var(--bg-surface);
  color: var(--text-strong);
}

.us-milestones--reorder .us-milestone__handle:focus-visible {
  outline: 0;
  box-shadow: var(--focus-ring);
  color: var(--text-strong);
}

@keyframes us-milestone-handle-in {
  from {
    opacity: 0;
  }
}

/* The row being dragged, as the IQA reorder lists draw it: its place in
   the list is a dashed placeholder, and its content, a touch see-through
   with a focus-coloured edge, follows the pointer above the others. */
.us-milestones--reorder .QueryTemplateSet > [data-us-dragging] {
  position: relative;
  z-index: 2;
}

.us-milestones--reorder .QueryTemplateSet > [data-us-dragging]::before {
  content: "";
  position: absolute;
  inset: calc(var(--us-reorder-tile) * -1);
  box-sizing: border-box;
  border: 2px dashed var(--border-focus);
  border-radius: calc(var(--radius-sm) + var(--us-reorder-tile));
  pointer-events: none;
}

.us-milestones--reorder .QueryTemplateSet > [data-us-dragging] > .QueryTemplateItem {
  position: relative;
  opacity: .8;
}

.us-milestones--reorder .QueryTemplateSet > [data-us-dragging] .us-milestone {
  background: var(--bg-surface);
  box-shadow:
    0 0 0 var(--us-reorder-tile) var(--bg-surface),
    0 0 0 calc(var(--us-reorder-tile) + 1px) var(--border-focus),
    var(--shadow-lg);
}

[data-us-milestones-dragging],
[data-us-milestones-dragging] * {
  cursor: grabbing !important;
  user-select: none;
}

@media (prefers-reduced-motion: reduce) {
  .us-milestones--reorder .us-milestone__handle {
    animation: none;
    transition: none;
  }
}

/* US-MILESTONE-ORDER:END */

/* US-TASKBAR-PIP:START */

/* Biscuit: 30% larger puppy drawing, attached floppy ears and daily greeting.
   Legacy pip-* hooks preserve client compatibility. Dark palette lives in zzDarkMode.css. */
:root {
  --us-pip-fur: #ebc492;
  --us-pip-fur-edge: #c39a6c;
  --us-pip-fur-light: #fff0d6;
  --us-pip-ear: #b98459;
  --us-pip-face: #483729;
  --us-pip-blush: #dfaca7;
  --us-pip-shine: #fffdf7;
  --us-pip-shadow: #203c351a;
  --us-pip-ear-edge: #986a48;
  --us-pip-collar: #6caa95;
  --us-pip-tag: #f6d66e;
  --us-pip-tongue: #dc9297;
}

#hd .us-taskbar__pip {
  --us-pip-enabled: 1;
  --pip-goodbye-duration: 3000ms;
  --pip-fur: var(--us-pip-fur);
  --pip-fur-edge: var(--us-pip-fur-edge);
  --pip-fur-light: var(--us-pip-fur-light);
  --pip-ear: var(--us-pip-ear);
  --pip-face: var(--us-pip-face);
  --pip-blush: var(--us-pip-blush);
  --pip-shine: var(--us-pip-shine);
  --pip-shadow: var(--us-pip-shadow);
  --pip-ear-edge: var(--us-pip-ear-edge);
  --pip-collar: var(--us-pip-collar);
  --pip-tag: var(--us-pip-tag);
  --pip-tongue: var(--us-pip-tongue);
  --biscuit-clip-height: 70.2px;
  position: relative;
  flex: 0 0 96px;
  width: 96px;
  height: 36px;
  margin-left: 10px;
  overflow: visible;
}

/* Biscuit sits outside #injected-taskbar, so the taskbar's own [hidden] rule
   no longer hides his button between visits. */
#hd .us-taskbar__pip-button[hidden] {
  display: none;
}

#hd .us-taskbar__pip *,
#hd .us-taskbar__pip *::after {
  box-sizing: border-box;
}

#hd .us-taskbar__pip-button {
  /* Extra headroom clears the hop; the wider slot fits ears throughout the tilt. */
  display: block;
  position: absolute;
  top: auto;
  bottom: calc(-1 * var(--pip-perch-offset, 0px));
  left: 0;
  width: 100%;
  height: var(--biscuit-clip-height);
  min-width: 0;
  min-height: 0;
  padding: 0;
  margin: 0;
  overflow: hidden;
  border: 0;
  border-radius: 6px 6px 0 0;
  background: transparent;
  box-shadow: none;
  color: var(--pip-face);
  font: inherit;
  line-height: 1;
  opacity: 1;
  cursor: pointer;
  transform: none;
  transition: none;
  appearance: none;
  -webkit-tap-highlight-color: transparent;
}

#hd .us-taskbar__pip-button:disabled {
  cursor: default;
}

#hd .us-taskbar__pip-button:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: -2px;
}

#hd .us-taskbar__pip .pip-visitor {
  position: absolute;
  bottom: 0;
  left: 50%;
  margin-left: -95px;
  width: 190px;
  height: 225px;
  transform: scale(.442);
  transform-origin: 50% 100%;
  pointer-events: none;
}

#hd .us-taskbar__pip .pip-character {
  position: absolute;
  bottom: -35px;
  left: 15px;
  width: 160px;
  height: 158px;
  background: none;
  border: 0;
  padding: 0;
  color: var(--pip-face);
  cursor: pointer;
  transform: translateY(155px);
  visibility: hidden;
  transition: transform 500ms ease-in, visibility 0s linear 500ms;
