@keyframes us-pip-happy-hop {
  0%,
  100% {
    transform: translateY(0) scale(1, 1);
  }

  18% {
    transform: translateY(8px) scale(1.08, .88);
  }

  42% {
    transform: translateY(-25px) scale(.96, 1.04);
  }

  56% {
    transform: translateY(-24px) scale(.98, 1.02);
  }

  78% {
    transform: translateY(2px) scale(1.06, .93);
  }

  90% {
    transform: translateY(-2px) scale(.99, 1.02);
  }
}

@keyframes us-pip-curious-tilt {
