  }

  35%,
  76% {
    transform: rotate(11deg) translateY(-2px);
  }
}

@keyframes us-pip-head-scratch {
  0%,
  100% {
    transform: translate(0,0) rotate(-8deg);
  }

  20%,
  36%,
  52%,
  68%,
  82% {
    transform: translate(-10px,-75px) rotate(-24deg);
  }

  28%,
  44%,
  60%,
  76% {
    transform: translate(-6px,-80px) rotate(-12deg);
  }
}

@keyframes us-pip-shy-goodbye {
  0% {
    transform: translateY(0);
  }

  /* First duck takes 180ms; the final dive takes 240ms. */
  6%,
  14% {
    transform: translateY(155px);
  }

  27%,
  73% {
    transform: translateY(32px);
  }

  78% {
    transform: translateY(38px);
  }

  85% {
    transform: translateY(-18px) rotate(-2deg);
  }

  89% {
    transform: translateY(-14px) rotate(2deg);
  }

  92% {
    transform: translateY(-10px);
    animation-timing-function: cubic-bezier(.55,0,1,.45);
  }

  100% {
    transform: translateY(155px);
  }
}

@keyframes us-pip-goodbye-look {
  0%,
  27%,
  100% {
    transform: rotate(-3deg);
  }

  31%,
  39% {
    transform: translateX(-4px) rotate(-8deg);
  }

  47%,
  55% {
    transform: translateX(4px) rotate(6deg);
  }

  63%,
  92% {
    transform: translateX(0) rotate(0deg);
  }
}

@keyframes us-pip-goodbye-eyes {
  0%,
  27%,
  100% {
    transform: translate(0,0);
    scale: 1;
  }

  31%,
  39% {
    transform: translate(-6px,0);
    scale: 1;
  }

  47%,
  55% {
    transform: translate(6px,0);
    scale: 1;
  }

  63%,
  73% {
    transform: translate(0,0);
    scale: 1;
  }

  78%,
  92% {
    transform: translate(0,-2px);
    scale: 1.2 1.25;
  }
}

@keyframes us-pip-goodbye-startle {
  0%,
  73%,
  100% {
    transform: scale(1);
  }

  78% {
    transform: scale(1.06,.92);
  }

  85%,
  89% {
    transform: scale(.96,1.08);
  }

  92% {
    transform: scale(1);
  }
}

@keyframes us-pip-goodbye-gasp {
  0%,
  73% {
    left: 49px;
    top: 66px;
    width: 14px;
    height: 7px;
    border-top-width: 0;
    border-radius: 0 0 12px 12px;
  }

  78%,
  100% {
    left: 50px;
    top: 65px;
    width: 11px;
    height: 14px;
    border-top-width: 2px;
    border-radius: 50%;
  }
