  73%,
  100% {
    transform: translateY(0) rotate(var(--pip-ear-rest));
  }

  80%,
  92% {
    transform: translateY(-7px) rotate(var(--pip-ear-alert));
  }
}

@keyframes us-pip-land {
  0% {
    transform: scale(1.04, .9);
  }

  45% {
    transform: scale(.96, 1.07);
  }

  75% {
    transform: scale(1.02, .98);
  }

  100% {
    transform: scale(1, 1);
  }
}

@keyframes us-pip-breathe {
  0%,
  100% {
    transform: scale(1, 1);
  }

  50% {
    transform: scale(1.014, .984) translateY(.6px);
  }
}

@keyframes us-pip-glance {
  0%,
  100% {
    transform: translate(0, 0);
  }

  25% {
    transform: translate(-2px, -.5px);
  }

  65% {
    transform: translate(2px, -.5px);
  }
}

@keyframes us-pip-blink {
  0%,
  100% {
    scale: 1 1;
  }

  40%,
  60% {
    scale: 1 .12;
  }
}

@keyframes us-biscuit-tail-wag {
  0%,
  100% {
    transform: rotate(-26deg);
  }

  50% {
    transform: rotate(-65deg);
  }
}

@keyframes us-biscuit-ear-flop {
  0%,
  100% {
    transform: rotate(14deg);
  }

  50% {
    transform: rotate(23deg);
  }
