  100% {
    transform: translate(0, 0) rotate(-8deg);
  }

  12%,
  32%,
  52%,
  72%,
  90% {
    transform: translate(8px, -29px) rotate(16deg);
  }

  22%,
  42%,
  62%,
  82% {
    transform: translate(10px, -31px) rotate(49deg);
  }
