@keyframes us-pip-bounce {
  0%,
  100% {
    transform: translateY(0) scale(1, 1);
  }

  12% {
    transform: translateY(-4px) scale(.98, 1.03);
  }

  22%,
  42%,
  62% {
    transform: translateY(-2px) scale(.99, 1.015);
  }

  32%,
  52%,
  72% {
    transform: translateY(0) scale(1.005, .995);
  }

  90% {
    transform: translateY(-1px) scale(1, 1);
  }
