  #hd .us-taskbar__pip .pip-character,
  #hd .us-taskbar__pip .pip-creature,
  #hd .us-taskbar__pip .pip-figure,
  #hd .us-taskbar__pip .pip-head,
  #hd .us-taskbar__pip .pip-eye,
  #hd .us-taskbar__pip .pip-ear,
  #hd .us-taskbar__pip .pip-mouth,
  #hd .us-taskbar__pip .pip-tail,
  #hd .us-taskbar__pip .pip-paw-right {
