  #hd .us-taskbar__pip .us-taskbar__pip-button:not(:disabled):hover .pip-ear-left {
    transform: rotate(14deg);
  }

  #hd .us-taskbar__pip .us-taskbar__pip-button:not(:disabled):hover .pip-ear-right {
    transform: rotate(-14deg);
  }

  #hd .us-taskbar__pip.is-waving .pip-paw-right {
